import { Store, setDeepValue, closeModal } from "../core/store.js";
import { debounce } from "../utils/fn.js";
import { dispatchAction } from "../controllers/actions.js";
import { renderApp } from "../views/layout.js";

export function registerBindings() {
  // Generic data-bind (input/select/textarea)
  document.addEventListener("input", (e) => {
    const el = e.target;
    const bind = el?.dataset?.bind;
    if (!bind) return;
    setDeepValue(Store, bind, el.value);
  });

  // Enter to close modal (Esc)
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && Store.ui.modal) {
      closeModal();
      renderApp();
    }
  });

  // Click actions
  document.addEventListener("click", async (e) => {
    const el = e.target?.closest?.("[data-action]");
    if (!el) return;
    e.preventDefault();
    await dispatchAction(el.dataset.action, el);
  });

  // (Reserved) Debounced search hooks
  document.addEventListener("keyup", debounce(() => {}, 250));
}

import { startRouter } from "./core/router.js";
import { registerBindings } from "./events/bindings.js";
import { renderApp } from "./views/layout.js";
import { initBootstrap } from "./services/bootstrap.js";
import { listInbox } from "./services/inbox.js";
import { listInward, listOutward } from "./services/correspondence.js";
import { listApprovals } from "./services/approvals.js";
import { listTasks } from "./services/tasks.js";
import { listNotifications, listAudit, listDirectory } from "./services/ops.js";
import { listMeetings } from "./services/meetings.js";
import { listBriefs } from "./services/briefs.js";
import { listDecisions } from "./services/decisions.js";

registerBindings();
startRouter();

await initBootstrap();

// Prime key queues in parallel (best-effort; demo/bootstrap may already fill them)
Promise.allSettled([
  listInbox(),
  listInward(),
  listOutward(),
  listApprovals(),
  listTasks(),
  listMeetings(),
  listBriefs(),
  listDecisions(),
  listNotifications(),
  listAudit(),
  listDirectory()
]).finally(() => renderApp());

import { CONFIG } from "../core/config.js";
import { callApi } from "../api/client.js";

export async function aiChat(messages) {
  const res = await callApi(CONFIG.ACTIONS.AI_CHAT, { messages });
  if (res.ok) {
    const data = res.data?.data ?? res.data;
    return data?.reply ?? data?.message ?? "OK";
  }
  return null;
}

import { CONFIG } from "../core/config.js";
import { Store } from "../core/store.js";
import { callApi } from "../api/client.js";
import { toast } from "../utils/toast.js";

export async function listApprovals() {
  const res = await callApi(CONFIG.ACTIONS.APPROVAL_LIST, { filters: Store.ui.filters.approvals });
  if (res.ok) {
    const data = res.data?.data ?? res.data;
    Store.entities.approvals = data?.items ?? data ?? [];
  }
  return Store.entities.approvals;
}

export async function decideApproval(approvalId, decision, comments) {
  const res = await callApi(CONFIG.ACTIONS.APPROVAL_DECIDE, { approvalId, decision, comments });
  Store.entities.approvals = Store.entities.approvals.map(a => a.id === approvalId ? { ...a, status: decision === "Approve" ? "Approved" : "Rejected", decisionAt: new Date().toISOString(), comments, _local: !res.ok } : a);
  toast(res.ok ? "success" : "info", res.ok ? "Decision recorded." : "Recorded locally (demo/offline).");
  return res.ok;
}

import { CONFIG } from "../core/config.js";
import { Store, setBusy } from "../core/store.js";
import { toast } from "../utils/toast.js";
import { callApi } from "../api/client.js";
import { demoBootstrap } from "../data/demo.js";

export async function initBootstrap() {
  setBusy(true, "Syncing Executive Hub…");
  try {
    const res = await callApi(CONFIG.ACTIONS.GET_BOOTSTRAP, {});
    if (res.ok) {
      // Expected backend response shape:
      // { ref:{departments,people}, entities:{inbox,inward,outward,minutes,approvals,briefs,decisions,meetings,tasks,projects,kpi,notifications,audit,sla,directory} }
      const data = res.data?.data ?? res.data;
      if (data?.ref) Store.ref = { ...Store.ref, ...data.ref };
      if (data?.entities) Store.entities = { ...Store.entities, ...data.entities };
      toast("success", "System synced.");
      return;
    }
    if (CONFIG.DEMO_FALLBACK) {
      const demo = demoBootstrap();
      Store.ref = { ...Store.ref, ...demo.ref };
      Store.entities = { ...Store.entities, ...demo.entities };
      toast("info", "Running in demo mode (API not configured / unavailable).");
      return;
    }
    toast("error", `Bootstrap failed: ${res.error || "Unknown error"}`);
  } finally {
    setBusy(false);
  }
}

import { CONFIG } from "../core/config.js";
import { Store } from "../core/store.js";
import { callApi } from "../api/client.js";
import { toast } from "../utils/toast.js";
import { uid } from "../utils/fn.js";

export async function listBriefs() {
  const res = await callApi(CONFIG.ACTIONS.BRIEF_LIST, {});
  if (res.ok) {
