export const safeLower = (v) => String(v ?? "").toLowerCase();
export const isoDate = (d) => {
  try {
    const x = (d instanceof Date) ? d : new Date(d);
    const yyyy = x.getFullYear();
    const mm = String(x.getMonth() + 1).padStart(2, "0");
    const dd = String(x.getDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  } catch {
    return "";
  }
};

export function debounce(fn, wait = 300) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), wait);
  };
}

export function escapeHtml(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

export function uid(prefix = "ID") {
  return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
}

import { clearToast, Store } from "../core/store.js";
import { renderApp } from "../views/layout.js";

export function toast(type, message) {
  Store.ui.toast = { type, message, ts: Date.now() };
  renderApp();
  setTimeout(() => {
    if (Store.ui.toast && Date.now() - Store.ui.toast.ts >= 3500) {
      clearToast();
      renderApp();
    }
  }, 3600);
}

import { escapeHtml } from "../../utils/fn.js";

export function badge(text, tone = "slate") {
  const t = escapeHtml(text);
  const cls = {
    slate: "bg-slate-100 text-slate-700",
    green: "bg-green-100 text-green-700",
    amber: "bg-amber-100 text-amber-800",
    red: "bg-red-100 text-red-700",
    blue: "bg-blue-100 text-blue-700",
    purple: "bg-purple-100 text-purple-700"
  }[tone] || "bg-slate-100 text-slate-700";
  return `<span class="px-2 py-0.5 rounded-full text-xs font-semibold ${cls}">${t}</span>`;
}

