.dgo-container-md { max-width: 960px; }
.dgo-container-lg { max-width: 1280px; }
.dgo-container-xl { max-width: 1536px; }
.dgo-container-fluid { max-width: none; }

.dgo-stack {
  display: flex;
  flex-direction: column;
  gap: var(--dgo-density-gap);
}

.dgo-row {
  display: flex;
  flex-direction: row;
  gap: var(--dgo-density-gap);
  align-items: center;
}

.dgo-grid {
  display: grid;
  gap: var(--dgo-space-4);
}

.dgo-grid-2 { grid-template-columns: repeat(2, 1fr); }
.dgo-grid-3 { grid-template-columns: repeat(3, 1fr); }
.dgo-grid-4 { grid-template-columns: repeat(4, 1fr); }

@media (max-width: 768px) {
  .dgo-grid-2, .dgo-grid-3, .dgo-grid-4 {
    grid-template-columns: 1fr;
  }
}

/* ============= DGO Mark / Logo ============= */

.dgo-mark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--dgo-font-display);
  user-select: none;
}

.dgo-mark .word {
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--dgo-primary);
  display: inline-flex;
  align-items: baseline;
}

.dgo-mark .o-orbit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 2px solid var(--dgo-accent);
  border-radius: 50%;
  position: relative;
  margin: 0 1px;
}

.dgo-mark .o-orbit::after {
  content: "";
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--dgo-primary);
}

.dgo-mark .sub {
  font-family: var(--dgo-font-sans);
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--dgo-ink-500);
}

.dgo-mark .stack {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.dgo-mark.on-dark .word { color: #fff; }
.dgo-mark.on-dark .o-orbit::after { background: #fff; }
.dgo-mark.on-dark .sub { color: rgba(255,255,255,0.6); }

/* Endorsement */
.dgo-endorse {
  font-family: var(--dgo-font-sans);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--dgo-ink-500);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.dgo-endorse::before {
  content: "";
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--dgo-accent);
}

/* ============= Buttons ============= */

.dgo-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: var(--dgo-density-pad) calc(var(--dgo-density-pad) * 1.75);
  border-radius: var(--dgo-radius-md);
  font-family: var(--dgo-font-sans);
  font-size: var(--dgo-fs-body-sm);
  font-weight: var(--dgo-fw-semibold);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--dgo-dur-fast) var(--dgo-ease-standard);
  text-decoration: none;
  white-space: nowrap;
  user-select: none;
  position: relative;
}

.dgo-btn:focus-visible {
  outline: none;
  box-shadow: var(--dgo-shadow-focus);
}

.dgo-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* Primary */
.dgo-btn-primary {
  background: var(--dgo-primary);
  color: #fff;
}

.dgo-btn-primary:hover {
  background: var(--dgo-primary-hover);
  box-shadow: var(--dgo-shadow-sm);
}

.dgo-btn-primary:active {
  background: var(--dgo-primary-deep);
  transform: translateY(1px);
}

/* Secondary */
.dgo-btn-secondary {
  background: #fff;
  color: var(--dgo-primary);
  border-color: var(--dgo-border);
}

.dgo-btn-secondary:hover {
  border-color: var(--dgo-primary);
  background: var(--dgo-primary-soft);
}

.dgo-btn-secondary:active {
  background: var(--dgo-primary-20);
}

/* Ghost */
.dgo-btn-ghost {
  background: transparent;
  color: var(--dgo-primary);
}

.dgo-btn-ghost:hover {
  background: var(--dgo-primary-soft);
}

.dgo-btn-ghost:active {
  background: var(--dgo-primary-20);
}

/* Danger */
.dgo-btn-danger {
  background: var(--dgo-danger);
  color: #fff;
}

.dgo-btn-danger:hover {
  background: #A30D26;
  box-shadow: var(--dgo-shadow-sm);
}

/* Success */
.dgo-btn-success {
  background: var(--dgo-accent);
  color: #fff;
}

.dgo-btn-success:hover {
  background: var(--dgo-accent-hover);
  box-shadow: var(--dgo-shadow-sm);
}

/* Sizes */
.dgo-btn-sm {
  padding: 6px 12px;
  font-size: var(--dgo-fs-caption);
}

.dgo-btn-lg {
  padding: 12px 24px;
  font-size: var(--dgo-fs-body);
}

/* Icon button */
.dgo-btn-icon {
  padding: var(--dgo-density-pad);
  aspect-ratio: 1;
}

/* ============= Inputs ============= */

.dgo-input,
.dgo-textarea,
.dgo-select {
  width: 100%;
  padding: 10px 12px;
  font-family: var(--dgo-font-body);
  font-size: var(--dgo-fs-body-sm);
  color: var(--dgo-ink-700);
  border: 1px solid var(--dgo-border);
  border-radius: var(--dgo-radius-md);
  outline: none;
  background: #fff;
  transition: all var(--dgo-dur-fast) var(--dgo-ease-standard);
}

.dgo-input::placeholder,
.dgo-textarea::placeholder {
  color: var(--dgo-ink-300);
}

.dgo-input:hover,
.dgo-textarea:hover,
.dgo-select:hover {
  border-color: var(--dgo-border-strong);
}

.dgo-input:focus,
.dgo-textarea:focus,
.dgo-select:focus {
  border-color: var(--dgo-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-primary) 18%, transparent);
}

.dgo-input:disabled,
.dgo-textarea:disabled,
.dgo-select:disabled {
  background: var(--dgo-surface-muted);
  cursor: not-allowed;
  opacity: 0.6;
}

.dgo-textarea {
  min-height: 120px;
  resize: vertical;
  font-family: var(--dgo-font-body);
}

.dgo-select {
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%235F5C5D' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 12px center;
  padding-right: 36px;
}

/* Input group */
.dgo-input-group {
  display: flex;
  gap: var(--dgo-space-2);
}

.dgo-input-group .dgo-input {
  flex: 1;
}

/* Form field */
.dgo-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.dgo-field label {
  font-family: var(--dgo-font-sans);
  font-size: var(--dgo-fs-body-sm);
  font-weight: var(--dgo-fw-semibold);
  color: var(--dgo-ink-900);
}

.dgo-field .helper {
  font-size: var(--dgo-fs-caption);
  color: var(--dgo-ink-500);
}

.dgo-field .error {
  font-size: var(--dgo-fs-caption);
  color: var(--dgo-danger-text);
}

.dgo-field.has-error .dgo-input,
.dgo-field.has-error .dgo-textarea,
.dgo-field.has-error .dgo-select {
  border-color: var(--dgo-danger);
}

/* Checkbox & Radio */
.dgo-checkbox,
.dgo-radio {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: var(--dgo-fs-body-sm);
  color: var(--dgo-ink-700);
}

.dgo-checkbox input,
.dgo-radio input {
  width: 18px;
  height: 18px;
  cursor: pointer;
  accent-color: var(--dgo-primary);
}

/* ============= Cards ============= */

.dgo-card {
  background: #fff;
  border: 1px solid var(--dgo-border);
  border-radius: var(--dgo-radius-lg);
  padding: var(--dgo-space-4);
  transition: all var(--dgo-dur-fast) var(--dgo-ease-standard);
}

.dgo-card-hover:hover {
  box-shadow: var(--dgo-shadow-md);
  border-color: var(--dgo-border-strong);
}

.dgo-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--dgo-space-3);
}

.dgo-card-title {
  font-family: var(--dgo-font-display);
  font-size: var(--dgo-fs-h4);
  font-weight: var(--dgo-fw-bold);
  color: var(--dgo-ink-900);
  margin: 0;
}

.dgo-card-subtitle {
  font-size: var(--dgo-fs-body-sm);
  color: var(--dgo-ink-500);
  margin: 4px 0 0 0;
}

.dgo-card-body {
  font-size: var(--dgo-fs-body-sm);
  color: var(--dgo-ink-700);
}

.dgo-card-footer {
  margin-top: var(--dgo-space-4);
  padding-top: var(--dgo-space-3);
  border-top: 1px solid var(--dgo-border);
  display: flex;
  gap: var(--dgo-space-2);
  align-items: center;
}

/* Frame card (large containers) */
.dgo-frame {
  background: var(--dgo-surface-alt);
  border-radius: var(--dgo-radius-frame);
  border: 1px solid var(--dgo-border);
  overflow: hidden;
  box-shadow: var(--dgo-shadow-sm);
}

/* ============= Badges / Pills ============= */

.dgo-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: var(--dgo-radius-pill);
  font-family: var(--dgo-font-sans);
  font-size: var(--dgo-fs-caption);
  font-weight: var(--dgo-fw-semibold);
  white-space: nowrap;
}

.dgo-pill .dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}

/* Status variants */
.dgo-pill-pending {
  background: var(--dgo-status-pending-bg);
  color: var(--dgo-status-pending-text);
}

.dgo-pill-routed {
  background: var(--dgo-status-routed-bg);
  color: var(--dgo-status-routed-text);
}

.dgo-pill-replied {
  background: var(--dgo-status-replied-bg);
  color: var(--dgo-status-replied-text);
}

.dgo-pill-action {
  background: var(--dgo-status-action-bg);
  color: var(--dgo-status-action-text);
}

.dgo-pill-draft {
  background: var(--dgo-status-draft-bg);
  color: var(--dgo-status-draft-text);
}

.dgo-pill-archived {
  background: var(--dgo-status-archived-bg);
  color: var(--dgo-status-archived-text);
}

.dgo-pill-escalated {
  background: var(--dgo-status-escalated-bg);
  color: var(--dgo-status-escalated-text);
}

/* Semantic variants */
.dgo-pill-success {
  background: var(--dgo-success-bg);
  color: var(--dgo-success-text);
}

.dgo-pill-warning {
  background: var(--dgo-warning-bg);
  color: var(--dgo-warning-text);
}

.dgo-pill-danger {
  background: var(--dgo-danger-bg);
  color: var(--dgo-danger-text);
}

.dgo-pill-info {
  background: var(--dgo-info-bg);
  color: var(--dgo-info-text);
}

/* ============= Tables ============= */

.dgo-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--dgo-fs-body-sm);
}

.dgo-table thead {
  border-bottom: 1px solid var(--dgo-border);
}

.dgo-table th {
  font-family: var(--dgo-font-sans);
  font-weight: var(--dgo-fw-semibold);
  font-size: var(--dgo-fs-caption);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--dgo-ink-500);
  text-align: left;
  padding: var(--dgo-density-pad) 12px;
}

.dgo-table td {
  padding: var(--dgo-density-pad) 12px;
  color: var(--dgo-ink-700);
  border-bottom: 1px solid var(--dgo-border);
}

.dgo-table tbody tr:hover {
  background: var(--dgo-surface-alt);
}

.dgo-table tbody tr:last-child td {
  border-bottom: none;
}

/* Compact table */
.dgo-table-compact th,
.dgo-table-compact td {
  padding: 6px 12px;
}

/* Bordered table */
.dgo-table-bordered {
  border: 1px solid var(--dgo-border);
}

.dgo-table-bordered td,
.dgo-table-bordered th {
  border-right: 1px solid var(--dgo-border);
}

.dgo-table-bordered td:last-child,
.dgo-table-bordered th:last-child {
  border-right: none;
}

/* ============= Navigation ============= */

.dgo-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dgo-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: var(--dgo-density-pad) 12px;
  border-radius: var(--dgo-radius-md);
  font-family: var(--dgo-font-sans);
  font-size: var(--dgo-fs-body-sm);
  font-weight: var(--dgo-fw-medium);
  color: rgba(255,255,255,0.78);
  cursor: pointer;
  text-decoration: none;
  transition: all var(--dgo-dur-fast) var(--dgo-ease-standard);
  position: relative;
}

.dgo-nav-item:hover {
  color: #fff;
  background: rgba(255,255,255,0.04);
}

.dgo-nav-item.active {
  background: rgba(255,255,255,0.08);
  color: #fff;
}

.dgo-nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  width: 3px;
  height: 16px;
  background: var(--dgo-accent);
  border-radius: 2px;
}

/* Horizontal nav */
.dgo-nav-horizontal {
  flex-direction: row;
  border-bottom: 1px solid var(--dgo-border);
}

.dgo-nav-horizontal .dgo-nav-item {
  color: var(--dgo-ink-700);
  border-radius: 0;
  border-bottom: 2px solid transparent;
  padding-bottom: 10px;
}

.dgo-nav-horizontal .dgo-nav-item:hover {
  color: var(--dgo-primary);
  background: transparent;
}

.dgo-nav-horizontal .dgo-nav-item.active {
  color: var(--dgo-primary);
  background: transparent;
  border-bottom-color: var(--dgo-accent);
}

.dgo-nav-horizontal .dgo-nav-item.active::before {
  display: none;
}

/* ============= Header ============= */

.dgo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--dgo-space-4) var(--dgo-space-6);
  background: #fff;
  border-bottom: 1px solid var(--dgo-border);
}

.dgo-header-dark {
  background: var(--dgo-surface-inverse);
  border-bottom-color: var(--dgo-border-on-green);
}

/* ============= Modal ============= */

.dgo-modal-backdrop {
  position: fixed;
  inset: 0;
  background: var(--dgo-surface-overlay);
  z-index: var(--dgo-z-modal-backdrop);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--dgo-space-4);
}

.dgo-modal {
  background: #fff;
  border-radius: var(--dgo-radius-xl);
  box-shadow: var(--dgo-shadow-xl);
  max-width: 560px;
  width: 100%;
  max-height: 90vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: var(--dgo-z-modal);
}

.dgo-modal-header {
  padding: var(--dgo-space-5);
  border-bottom: 1px solid var(--dgo-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.dgo-modal-title {
  font-family: var(--dgo-font-display);
  font-size: var(--dgo-fs-h3);
  font-weight: var(--dgo-fw-bold);
  color: var(--dgo-ink-900);
  margin: 0;
}

.dgo-modal-body {
  padding: var(--dgo-space-5);
  overflow-y: auto;
  flex: 1;
}

.dgo-modal-footer {
  padding: var(--dgo-space-4) var(--dgo-space-5);
  border-top: 1px solid var(--dgo-border);
  display: flex;
  gap: var(--dgo-space-2);
  justify-content: flex-end;
}

/* ============= Alerts ============= */

.dgo-alert {
  padding: var(--dgo-space-4);
  border-radius: var(--dgo-radius-md);
  border: 1px solid;
  display: flex;
  align-items: flex-start;
  gap: var(--dgo-space-3);
  font-size: var(--dgo-fs-body-sm);
}

.dgo-alert-success {
  background: var(--dgo-success-bg);
  border-color: var(--dgo-success);
  color: var(--dgo-success-text);
}

.dgo-alert-warning {
  background: var(--dgo-warning-bg);
  border-color: var(--dgo-warning);
  color: var(--dgo-warning-text);
}

.dgo-alert-danger {
  background: var(--dgo-danger-bg);
  border-color: var(--dgo-danger);
  color: var(--dgo-danger-text);
}

.dgo-alert-info {
  background: var(--dgo-info-bg);
  border-color: var(--dgo-info);
  color: var(--dgo-info-text);
}

/* ============= Sidebar ============= */

.dgo-sidebar {
  width: 240px;
  height: 100vh;
  background: var(--dgo-surface-inverse);
  padding: var(--dgo-space-5) var(--dgo-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--dgo-space-6);
  position: fixed;
  left: 0;
  top: 0;
}

.dgo-sidebar-brand {
  padding-bottom: var(--dgo-space-4);
  border-bottom: 1px solid var(--dgo-border-on-green);
}

/* ============= Divider ============= */

.dgo-divider {
  height: 1px;
  background: var(--dgo-border);
  border: none;
  margin: var(--dgo-space-4) 0;
}

.dgo-divider-strong {
  background: var(--dgo-border-strong);
}

/* ============= Dropdown ============= */

.dgo-dropdown {
  position: relative;
  display: inline-block;
}

.dgo-dropdown-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  background: #fff;
  border: 1px solid var(--dgo-border);
  border-radius: var(--dgo-radius-md);
  box-shadow: var(--dgo-shadow-lg);
  min-width: 200px;
  padding: var(--dgo-space-2);
  z-index: var(--dgo-z-dropdown);
  display: none;
}

.dgo-dropdown.open .dgo-dropdown-menu {
  display: block;
}

.dgo-dropdown-item {
  display: flex;
  align-items: center;
  gap: var(--dgo-space-2);
  padding: var(--dgo-space-2) var(--dgo-space-3);
  border-radius: var(--dgo-radius-sm);
  font-size: var(--dgo-fs-body-sm);
  color: var(--dgo-ink-700);
  cursor: pointer;
  transition: background var(--dgo-dur-fast) var(--dgo-ease-standard);
}

.dgo-dropdown-item:hover {
  background: var(--dgo-surface-alt);
}

.dgo-dropdown-divider {
  height: 1px;
  background: var(--dgo-border);
  margin: var(--dgo-space-2) 0;
}

/* ============= Loading Spinner ============= */

.dgo-spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--dgo-border);
  border-top-color: var(--dgo-primary);
  border-radius: 50%;
  animation: dgo-spin 0.6s linear infinite;
}

@keyframes dgo-spin {
  to { transform: rotate(360deg); }
}

.dgo-spinner-sm { width: 16px; height: 16px; border-width: 2px; }
.dgo-spinner-lg { width: 32px; height: 32px; border-width: 3px; }

/* ============================================
   DGO Digital Ops — Complete Design Tokens
   Standalone system (does NOT import NITDA)
   ============================================ */

/* Google Fonts: Outfit for display/headings */
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;600;700;800&display=swap');

:root {
  /* ============= Color Palette ============= */

  /* Primary */
  --dgo-primary:           #05583B;
  --dgo-primary-hover:     #033F2A;
  --dgo-primary-deep:      #022819;
  --dgo-primary-soft:      #E6EEEB;
  --dgo-primary-10:        #F2F7F5;
  --dgo-primary-20:        #D9E8E1;
  --dgo-primary-40:        #99C2B3;
  --dgo-primary-80:        #4D957B;

  /* Accent (Smart Green) */
  --dgo-accent:            #17B255;
  --dgo-accent-hover:      #119143;
  --dgo-accent-soft:       #E6F7ED;
  --dgo-accent-40:         #8BD9A9;
  --dgo-accent-80:         #45C578;

  /* Neutrals / Ink */
  --dgo-ink-900:           #1B1A1A;
  --dgo-ink-800:           #2D2C2C;
  --dgo-ink-700:           #373435;
  --dgo-ink-600:           #4A4849;
  --dgo-ink-500:           #5F5C5D;
  --dgo-ink-400:           #807D7E;
  --dgo-ink-300:           #A09E9F;
  --dgo-ink-200:           #C4C3C3;
  --dgo-ink-100:           #E0DFDF;
  --dgo-ink-50:            #F5F5F5;

  /* Surfaces */
  --dgo-surface:           #FFFFFF;
  --dgo-surface-alt:       #FAF9F9;
  --dgo-surface-muted:     #F5F4F4;
  --dgo-surface-inverse:   #0B2A1F;
  --dgo-surface-overlay:   rgba(27, 26, 26, 0.6);

  /* Borders */
  --dgo-border:            #E8E6E7;
  --dgo-border-strong:     #C4C3C3;
  --dgo-border-on-green:   rgba(255, 255, 255, 0.2);

  /* Semantic */
  --dgo-success:           #17B255;
  --dgo-success-bg:        rgba(23, 178, 85, 0.15);
  --dgo-success-text:      #119143;

  --dgo-warning:           #E1A100;
  --dgo-warning-bg:        rgba(225, 161, 0, 0.15);
  --dgo-warning-text:      #7A5800;

  --dgo-danger:            #C8102E;
  --dgo-danger-bg:         rgba(200, 16, 46, 0.12);
  --dgo-danger-text:       #A30D26;

  --dgo-info:              #0B6BB0;
  --dgo-info-bg:           rgba(11, 107, 176, 0.12);
  --dgo-info-text:         #0B6BB0;

  /* Status colors (extended) */
  --dgo-status-pending-bg:       rgba(225, 161, 0, 0.15);
  --dgo-status-pending-text:     #7A5800;
  --dgo-status-routed-bg:        rgba(11, 107, 176, 0.12);
  --dgo-status-routed-text:      #0B6BB0;
  --dgo-status-replied-bg:       rgba(23, 178, 85, 0.15);
  --dgo-status-replied-text:     #119143;
  --dgo-status-action-bg:        rgba(200, 16, 46, 0.12);
  --dgo-status-action-text:      #A30D26;
  --dgo-status-draft-bg:         var(--dgo-primary-soft);
  --dgo-status-draft-text:       var(--dgo-primary);
  --dgo-status-archived-bg:      rgba(95, 92, 93, 0.1);
  --dgo-status-archived-text:    #5F5C5D;
  --dgo-status-escalated-bg:     rgba(200, 16, 46, 0.18);
  --dgo-status-escalated-text:   #780820;

  /* Data visualization — categorical (8 colors) */
  --dgo-viz-1:             #05583B;
  --dgo-viz-2:             #17B255;
  --dgo-viz-3:             #0B6BB0;
  --dgo-viz-4:             #E1A100;
  --dgo-viz-5:             #C8102E;
  --dgo-viz-6:             #4538D9;
  --dgo-viz-7:             #7A5800;
  --dgo-viz-8:             #A30D26;

  /* Data visualization — sequential (5-step green) */
  --dgo-viz-seq-1:         #E6EEEB;
  --dgo-viz-seq-2:         #99C2B3;
  --dgo-viz-seq-3:         #4D957B;
  --dgo-viz-seq-4:         #05583B;
  --dgo-viz-seq-5:         #033F2A;

  /* ============= Typography ============= */

  /* Font families */
  --dgo-font-display:      'Outfit', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --dgo-font-sans:         'Outfit', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --dgo-font-body:         Verdana, Geneva, 'DejaVu Sans', sans-serif;
  --dgo-font-mono:         'SF Mono', Consolas, 'Courier New', monospace;

  /* Font sizes */
  --dgo-fs-display:        42px;
  --dgo-fs-display-sm:     36px;
  --dgo-fs-h1:             32px;
  --dgo-fs-h2:             24px;
  --dgo-fs-h3:             18px;
  --dgo-fs-h4:             16px;
  --dgo-fs-body:           14px;
  --dgo-fs-body-sm:        13px;
  --dgo-fs-caption:        11px;
  --dgo-fs-overline:       10px;

  /* Font weights */
  --dgo-fw-regular:        400; /* @kind font */
  --dgo-fw-medium:         500; /* @kind font */
  --dgo-fw-semibold:       600; /* @kind font */
  --dgo-fw-bold:           700; /* @kind font */
  --dgo-fw-black:          800; /* @kind font */

  /* Line heights */
  --dgo-lh-tight:          1.2; /* @kind font */
  --dgo-lh-snug:           1.4; /* @kind font */
  --dgo-lh-normal:         1.5; /* @kind font */
  --dgo-lh-relaxed:        1.7; /* @kind font */

  /* Letter spacing */
  --dgo-ls-tight:          -0.02em; /* @kind font */
  --dgo-ls-normal:         0; /* @kind font */
  --dgo-ls-wide:           0.12em; /* @kind font */
  --dgo-ls-extra-wide:     0.18em; /* @kind font */

  /* ============= Spacing ============= */

  --dgo-space-1:           4px;
  --dgo-space-2:           8px;
  --dgo-space-3:           12px;
  --dgo-space-4:           16px;
  --dgo-space-5:           20px;
  --dgo-space-6:           24px;
  --dgo-space-7:           32px;
  --dgo-space-8:           40px;
  --dgo-space-9:           48px;
  --dgo-space-10:          64px;
  --dgo-space-11:          80px;
  --dgo-space-12:          96px;

  /* Density modes */
  --dgo-density-pad:       8px;    /* compact */
  --dgo-density-row:       40px;   /* compact row height */
  --dgo-density-gap:       12px;   /* default gap */

  /* ============= Border Radius ============= */

  --dgo-radius-xs:         4px;
  --dgo-radius-sm:         6px;
  --dgo-radius-md:         8px;
  --dgo-radius-lg:         10px;
  --dgo-radius-xl:         12px;
  --dgo-radius-2xl:        16px;
  --dgo-radius-pill:       999px;
  --dgo-radius-frame:      18px;   /* large containers */

  /* ============= Elevation (Shadows) ============= */

  --dgo-shadow-xs:         0 1px 2px rgba(5, 88, 59, 0.05);
  --dgo-shadow-sm:         0 1px 3px rgba(5, 88, 59, 0.08);
  --dgo-shadow-md:         0 4px 6px rgba(5, 88, 59, 0.1);
  --dgo-shadow-lg:         0 10px 15px rgba(5, 88, 59, 0.12);
  --dgo-shadow-xl:         0 20px 25px rgba(5, 88, 59, 0.15);
  --dgo-shadow-focus:      0 0 0 3px rgba(23, 178, 85, 0.3);

  /* ============= Motion ============= */

  --dgo-ease-standard:     cubic-bezier(0.2, 0, 0, 1); /* @kind other */
  --dgo-ease-emphasis:     cubic-bezier(0.4, 0, 0.2, 1); /* @kind other */
  --dgo-ease-in:           cubic-bezier(0.4, 0, 1, 1); /* @kind other */
  --dgo-ease-out:          cubic-bezier(0, 0, 0.2, 1); /* @kind other */

  --dgo-dur-fast:          150ms; /* @kind other */
  --dgo-dur-base:          200ms; /* @kind other */
  --dgo-dur-slow:          300ms; /* @kind other */

  /* ============= Z-index Scale ============= */

  --dgo-z-base:            1; /* @kind other */
  --dgo-z-dropdown:        1000; /* @kind other */
  --dgo-z-sticky:          1020; /* @kind other */
  --dgo-z-fixed:           1030; /* @kind other */
  --dgo-z-modal-backdrop:  1040; /* @kind other */
  --dgo-z-modal:           1050; /* @kind other */
  --dgo-z-popover:         1060; /* @kind other */
  --dgo-z-tooltip:         1070; /* @kind other */
}

/* ============= Density Mode Overrides ============= */

[data-dgo-density="comfortable"] {
  --dgo-density-pad:       14px;
  --dgo-density-row:       52px;
  --dgo-density-gap:       16px;
}

/* ============= Reduced Motion ============= */

@media (prefers-reduced-motion: reduce) {
  :root {
    --dgo-dur-fast:        0ms; /* @kind other */
    --dgo-dur-base:        0ms; /* @kind other */
    --dgo-dur-slow:        0ms; /* @kind other */
  }
}

/* ============= Base Styles ============= */

.dgo {
  font-family: var(--dgo-font-body);
  font-size: var(--dgo-fs-body);
  line-height: var(--dgo-lh-normal);
  color: var(--dgo-ink-700);
  background: var(--dgo-surface);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.dgo h1, .dgo h2, .dgo h3, .dgo h4, .dgo h5, .dgo h6 {
  font-family: var(--dgo-font-display);
  font-weight: var(--dgo-fw-bold);
  line-height: var(--dgo-lh-tight);
  color: var(--dgo-ink-900);
  margin: 0;
}

.dgo h1 { font-size: var(--dgo-fs-h1); }
.dgo h2 { font-size: var(--dgo-fs-h2); }
.dgo h3 { font-size: var(--dgo-fs-h3); }
.dgo h4 { font-size: var(--dgo-fs-h4); }

.dgo p {
  margin: 0 0 var(--dgo-space-4) 0;
}

.dgo a {
  color: var(--dgo-primary);
  text-decoration: none;
  transition: color var(--dgo-dur-fast) var(--dgo-ease-standard);
}

.dgo a:hover {
  color: var(--dgo-accent);
}

.dgo strong, .dgo b {
  font-weight: var(--dgo-fw-semibold);
}

.dgo small {
  font-size: var(--dgo-fs-caption);
  color: var(--dgo-ink-500);
}

/* ============= Utility Classes ============= */

.dgo-text-muted { color: var(--dgo-ink-500); }
.dgo-text-subtle { color: var(--dgo-ink-400); }
.dgo-text-primary { color: var(--dgo-primary); }
.dgo-text-accent { color: var(--dgo-accent); }
.dgo-text-success { color: var(--dgo-success-text); }
.dgo-text-warning { color: var(--dgo-warning-text); }
.dgo-text-danger { color: var(--dgo-danger-text); }

.dgo-bg-surface { background: var(--dgo-surface); }
.dgo-bg-alt { background: var(--dgo-surface-alt); }
.dgo-bg-muted { background: var(--dgo-surface-muted); }

.dgo-border { border: 1px solid var(--dgo-border); }
.dgo-border-t { border-top: 1px solid var(--dgo-border); }
.dgo-border-b { border-bottom: 1px solid var(--dgo-border); }
.dgo-border-l { border-left: 1px solid var(--dgo-border); }
.dgo-border-r { border-right: 1px solid var(--dgo-border); }

.dgo-rounded-sm { border-radius: var(--dgo-radius-sm); }
.dgo-rounded { border-radius: var(--dgo-radius-md); }
.dgo-rounded-lg { border-radius: var(--dgo-radius-lg); }
.dgo-rounded-xl { border-radius: var(--dgo-radius-xl); }
.dgo-rounded-pill { border-radius: var(--dgo-radius-pill); }

.dgo-shadow-sm { box-shadow: var(--dgo-shadow-sm); }
.dgo-shadow { box-shadow: var(--dgo-shadow-md); }
.dgo-shadow-lg { box-shadow: var(--dgo-shadow-lg); }
.dgo-shadow-xl { box-shadow: var(--dgo-shadow-xl); }

/* ============================================================
   DGO v2.0 — Base typography + page chrome
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap');

html, body {
  font-family: var(--dgo-family-sans);
  font-size: var(--dgo-type-body);
  line-height: var(--dgo-lh-150);
  color: var(--dgo-color-fg-default);
  background: var(--dgo-color-surface-page);
}

/* Headings */
h1, h2, h3, h4, h5, h6,
.dgo-h1, .dgo-h2, .dgo-h3, .dgo-h4, .dgo-h5, .dgo-h6,
.dgo-display, .dgo-display-xl, .dgo-display-xxl {
  font-family: var(--dgo-family-display);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-tight);
  line-height: var(--dgo-lh-120);
  color: var(--dgo-color-fg-strong);
  text-wrap: balance;
}

.dgo-display-xxl { font-size: var(--dgo-type-display-xxl); font-weight: var(--dgo-wt-800); letter-spacing: var(--dgo-tr-tightest); }
.dgo-display-xl  { font-size: var(--dgo-type-display-xl);  font-weight: var(--dgo-wt-800); letter-spacing: var(--dgo-tr-tightest); }
.dgo-display     { font-size: var(--dgo-type-display);     font-weight: var(--dgo-wt-700); letter-spacing: var(--dgo-tr-tight); }
h1, .dgo-h1 { font-size: var(--dgo-type-h1); }
h2, .dgo-h2 { font-size: var(--dgo-type-h2); }
h3, .dgo-h3 { font-size: var(--dgo-type-h3); }
h4, .dgo-h4 { font-size: var(--dgo-type-h4); }
h5, .dgo-h5 { font-size: var(--dgo-type-body-lg); }
h6, .dgo-h6 { font-size: var(--dgo-type-body); letter-spacing: var(--dgo-tr-wide); text-transform: uppercase; }

/* Body */
p, .dgo-body { font-size: var(--dgo-type-body); line-height: var(--dgo-lh-150); text-wrap: pretty; }
.dgo-body-lg { font-size: var(--dgo-type-body-lg); line-height: var(--dgo-lh-150); }
.dgo-body-sm { font-size: var(--dgo-type-body-sm); line-height: var(--dgo-lh-140); }
.dgo-caption { font-size: var(--dgo-type-caption); line-height: var(--dgo-lh-140); color: var(--dgo-color-fg-muted); }
.dgo-overline {
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-widest);
  text-transform: uppercase;
  color: var(--dgo-color-fg-muted);
}

a, .dgo-link {
  color: var(--dgo-color-fg-link);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  transition: color var(--dgo-motion-state),
              text-decoration-color var(--dgo-motion-state);
}
a:hover, .dgo-link:hover {
  color: var(--dgo-color-fg-link-hover);
  text-decoration-color: currentColor;
}

strong, b { font-weight: var(--dgo-wt-600); color: var(--dgo-color-fg-strong); }
small { font-size: var(--dgo-type-caption); color: var(--dgo-color-fg-muted); }

code, kbd, samp, pre {
  font-family: var(--dgo-family-mono);
  font-size: 0.92em;
}

/* Selection */
::selection {
  background: color-mix(in srgb, var(--dgo-smart-400) 35%, transparent);
  color: var(--dgo-color-fg-strong);
}

/* Accessibility utilities */
.dgo-visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.dgo-skip-link {
  position: absolute;
  inset-inline-start: var(--dgo-s-3);
  inset-block-start: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  background: var(--dgo-color-surface-page);
  color: var(--dgo-color-fg-link);
  border: 2px solid var(--dgo-color-border-focus);
  border-radius: var(--dgo-radius-control);
  font-weight: var(--dgo-wt-600);
  transform: translateY(-200%);
  transition: transform var(--dgo-motion-state);
  z-index: var(--dgo-z-toast);
}
.dgo-skip-link:focus { transform: translateY(0); }

/* Print-friendly defaults */
@media print {
  body { background: #fff; color: #000; }
  a { color: #000; text-decoration: underline; }
  a[href^="http"]::after { content: " (" attr(href) ")"; font-size: 0.85em; }
  .dgo-no-print { display: none !important; }
}

/* Container */
.dgo-container {
  width: 100%;
  max-width: var(--dgo-c-wide);
  margin-inline: auto;
  padding-inline: var(--dgo-s-6);
}
.dgo-container--narrow  { max-width: var(--dgo-c-narrow); }
.dgo-container--text    { max-width: var(--dgo-c-text); }
.dgo-container--content { max-width: var(--dgo-c-content); }
.dgo-container--full    { max-width: var(--dgo-c-full); }

@media (max-width: 600px) {
  .dgo-container { padding-inline: var(--dgo-s-4); }
}

/* ============================================================
   DGO Design System v2.0 — Component Library
   ============================================================
   Organised by family; BEM under `.dgo-` namespace.
   Every value references a token — no hard-coded hex/px/ms.
   ------------------------------------------------------------
   Index:
   1.  Button             7.  Pill / Badge / Tag      13. Sidebar
   2.  Input / Textarea   8.  Avatar                  14. Topbar
   3.  Select             9.  Card                    15. Tabs
   4.  Checkbox / Radio   10. Alert / Banner          16. Breadcrumb
   5.  Switch             11. Toast                   17. Stepper / Pagination
   6.  Search             12. Modal / Drawer          18. Table / Data grid
                          19. Tooltip / Popover       20. Menu / Dropdown
                          21. Empty / Error state     22. Progress / Spinner
                          23. Skeleton                24. Metric / Stat
                          25. Kbd / Code              26. Chip / Filter bar
   ============================================================ */

@layer dgo-reset, dgo-base, dgo-component, dgo-utility;

/* ============================================================
   1 · BUTTON
   ============================================================
   States: default · hover · focus-visible · active · disabled · loading
   Variants: primary · secondary · tertiary · ghost · danger
   Sizes: sm · md · lg
   ============================================================ */
.dgo-btn {
  --_h: var(--dgo-btn-h-md);
  --_px: var(--dgo-btn-px-md);
  --_fs: var(--dgo-type-body);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--dgo-s-2);
  block-size: var(--_h);
  padding-inline: var(--_px);
  font-family: var(--dgo-family-sans);
  font-size: var(--_fs);
  font-weight: var(--dgo-btn-fw);
  line-height: 1;
  border: 1px solid transparent;
  border-radius: var(--dgo-btn-radius);
  cursor: pointer;
  user-select: none;
  text-decoration: none;
  white-space: nowrap;
  transition:
    background-color var(--dgo-motion-state),
    border-color var(--dgo-motion-state),
    color var(--dgo-motion-state),
    box-shadow var(--dgo-motion-state),
    transform var(--dgo-dur-instant) var(--dgo-ease-sharp);
  min-inline-size: var(--_h); /* hit area floor */
}

.dgo-btn:focus-visible { box-shadow: var(--dgo-focus-ring); }
.dgo-btn:active:not(:disabled) { transform: translateY(1px); }
.dgo-btn:disabled,
.dgo-btn[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
  pointer-events: none;
}

.dgo-btn--sm {
  block-size: var(--dgo-btn-h-sm);
  min-inline-size: var(--dgo-btn-h-sm);
  padding-inline: var(--dgo-btn-px-sm);
  font-size: var(--dgo-type-body-sm);
}
.dgo-btn--lg {
  block-size: var(--dgo-btn-h-lg);
  min-inline-size: var(--dgo-btn-h-lg);
  padding-inline: var(--dgo-btn-px-lg);
  font-size: var(--dgo-type-body-lg);
}
.dgo-btn--block { inline-size: 100%; }

/* Primary */
.dgo-btn--primary {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--primary:hover:not(:disabled) { background: var(--dgo-color-action-primary-hover); box-shadow: var(--dgo-shadow-2); }
.dgo-btn--primary:active:not(:disabled) { background: var(--dgo-color-action-primary-press); }

/* Secondary — outline */
.dgo-btn--secondary {
  background: transparent;
  color: var(--dgo-color-action-primary);
  border-color: var(--dgo-color-border-strong);
}
.dgo-btn--secondary:hover:not(:disabled) {
  border-color: var(--dgo-color-action-primary);
  background: var(--dgo-color-action-secondary-hover);
}
.dgo-btn--secondary:active:not(:disabled) { background: var(--dgo-color-action-secondary-press); }

/* Tertiary — text + subtle hover */
.dgo-btn--tertiary,
.dgo-btn--ghost {
  background: transparent;
  color: var(--dgo-color-action-primary);
}
.dgo-btn--tertiary:hover:not(:disabled),
.dgo-btn--ghost:hover:not(:disabled) { background: var(--dgo-color-action-secondary-hover); }

/* Danger */
.dgo-btn--danger {
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--danger:hover:not(:disabled) { background: var(--dgo-color-action-danger-hover); }

/* Accent */
.dgo-btn--accent {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
}
.dgo-btn--accent:hover:not(:disabled) { background: var(--dgo-color-action-accent-hover); }

/* Icon button */
.dgo-btn--icon { padding-inline: 0; inline-size: var(--_h); }

/* Loading */
.dgo-btn[data-loading="true"] { color: transparent; position: relative; }
.dgo-btn[data-loading="true"]::after {
  content: "";
  position: absolute;
  inline-size: 1em; block-size: 1em;
  border: 2px solid currentColor;
  border-block-start-color: transparent;
  border-radius: 50%;
  color: var(--dgo-color-fg-on-brand);
  animation: dgo-spin 0.6s linear infinite;
}
.dgo-btn--secondary[data-loading="true"]::after,
.dgo-btn--tertiary[data-loading="true"]::after,
.dgo-btn--ghost[data-loading="true"]::after { color: var(--dgo-color-action-primary); }

@keyframes dgo-spin { to { transform: rotate(360deg); } }

/* Button group */
.dgo-btn-group { display: inline-flex; }
.dgo-btn-group .dgo-btn {
  border-radius: 0;
}
.dgo-btn-group .dgo-btn:first-child { border-start-start-radius: var(--dgo-btn-radius); border-end-start-radius: var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn:last-child  { border-start-end-radius:   var(--dgo-btn-radius); border-end-end-radius:   var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn + .dgo-btn { margin-inline-start: -1px; }

/* ============================================================
   2 · INPUT / TEXTAREA
   ============================================================ */
.dgo-input,
.dgo-textarea,
.dgo-select__field {
  display: block;
  inline-size: 100%;
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-input-px);
  padding-block: 0;
  font-family: var(--dgo-family-sans);
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  background: var(--dgo-input-bg);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  transition: border-color var(--dgo-motion-state), box-shadow var(--dgo-motion-state), background-color var(--dgo-motion-state);
}
.dgo-input::placeholder,
.dgo-textarea::placeholder { color: var(--dgo-input-placeholder); }

.dgo-input:hover:not(:disabled),
.dgo-textarea:hover:not(:disabled),
.dgo-select__field:hover:not(:disabled) { border-color: var(--dgo-input-border-hover); }

.dgo-input:focus-visible,
.dgo-textarea:focus-visible,
.dgo-select__field:focus-visible {
  outline: none;
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}

.dgo-input:disabled,
.dgo-textarea:disabled,
.dgo-select__field:disabled {
  background: var(--dgo-input-bg-disabled);
  color: var(--dgo-color-fg-disabled);
  cursor: not-allowed;
}

.dgo-input[aria-invalid="true"],
.dgo-textarea[aria-invalid="true"],
.dgo-select__field[aria-invalid="true"] { border-color: var(--dgo-input-border-error); }

.dgo-textarea {
  block-size: auto;
  min-block-size: calc(var(--dgo-input-h) * 2.5);
  padding-block: var(--dgo-s-2);
  resize: vertical;
  line-height: var(--dgo-lh-150);
}

/* Form field wrapper */
.dgo-field { display: flex; flex-direction: column; gap: var(--dgo-s-1_5); }
.dgo-field__label {
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
  color: var(--dgo-color-fg-default);
}
.dgo-field__label--req::after { content: " *"; color: var(--dgo-color-action-danger); }
.dgo-field__help { font-size: var(--dgo-type-caption); color: var(--dgo-color-fg-muted); }
.dgo-field__error {
  font-size: var(--dgo-type-caption);
  color: var(--dgo-color-danger-subtle-fg);
  display: flex; align-items: center; gap: var(--dgo-s-1);
}

/* Input with leading/trailing affordance */
.dgo-input-group {
  display: flex; align-items: stretch;
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  overflow: hidden;
}
.dgo-input-group:focus-within {
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}
.dgo-input-group > .dgo-input,
.dgo-input-group > .dgo-select__field {
  border: 0; border-radius: 0;
}
.dgo-input-group > .dgo-input:focus-visible { box-shadow: none; }
.dgo-input-group__addon {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  padding-inline: var(--dgo-s-3);
  color: var(--dgo-color-fg-muted);
  background: var(--dgo-color-surface-sunken);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   3 · SELECT (native styled)
   ============================================================ */
.dgo-select { position: relative; display: block; }
.dgo-select__field {
  appearance: none;
  -webkit-appearance: none;
  padding-inline-end: calc(var(--dgo-input-px) + 24px);
  cursor: pointer;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8' fill='none'><path d='M1 1.5L6 6.5L11 1.5' stroke='%235F5C5D' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right var(--dgo-s-3) center;
}
[dir="rtl"] .dgo-select__field {
  background-position: left var(--dgo-s-3) center;
}

/* ============================================================
   4 · CHECKBOX / RADIO
   ============================================================ */
.dgo-check, .dgo-radio {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  cursor: pointer; user-select: none;
  font-size: var(--dgo-type-body);
}
.dgo-check input[type="checkbox"],
.dgo-radio input[type="radio"] {
  inline-size: 18px; block-size: 18px;
  margin: 0;
  accent-color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-check input:focus-visible,
.dgo-radio input:focus-visible {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   5 · SWITCH
   ============================================================ */
.dgo-switch {
  position: relative;
  display: inline-flex;
  inline-size: 38px; block-size: 22px;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-ink-200);
  cursor: pointer;
  transition: background-color var(--dgo-motion-state);
  flex-shrink: 0;
}
.dgo-switch::before {
  content: "";
  position: absolute;
  inset-inline-start: 2px;
  inset-block-start: 2px;
  inline-size: 18px; block-size: 18px;
  border-radius: 50%;
  background: var(--dgo-color-surface-page);
  box-shadow: var(--dgo-shadow-1);
  transition: transform var(--dgo-motion-state);
}
.dgo-switch input { position: absolute; opacity: 0; inset: 0; cursor: pointer; }
.dgo-switch:has(input:checked) { background: var(--dgo-color-action-primary); }
.dgo-switch:has(input:checked)::before { transform: translateX(16px); }
[dir="rtl"] .dgo-switch:has(input:checked)::before { transform: translateX(-16px); }
.dgo-switch:has(input:focus-visible) {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   6 · SEARCH
   ============================================================ */
.dgo-search {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-s-3);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  color: var(--dgo-color-fg-muted);
  transition: border-color var(--dgo-motion-state);
}
.dgo-search:focus-within { border-color: var(--dgo-color-action-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent); }
.dgo-search input {
  flex: 1; border: 0; background: transparent;
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  outline: none;
}

/* ============================================================
   7 · PILL / BADGE / TAG / CHIP
   ============================================================ */
.dgo-pill {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-badge-h);
  padding-inline: var(--dgo-badge-px);
  font-size: var(--dgo-badge-fs);
  font-weight: var(--dgo-badge-fw);
  line-height: 1;
  border-radius: var(--dgo-badge-radius);
  white-space: nowrap;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
}
.dgo-pill__dot { inline-size: 6px; block-size: 6px; border-radius: 50%; background: currentColor; }

.dgo-pill--pending   { background: var(--dgo-color-status-pending-bg);   color: var(--dgo-color-status-pending-fg); }
.dgo-pill--routed    { background: var(--dgo-color-status-routed-bg);    color: var(--dgo-color-status-routed-fg); }
.dgo-pill--replied   { background: var(--dgo-color-status-replied-bg);   color: var(--dgo-color-status-replied-fg); }
.dgo-pill--action    { background: var(--dgo-color-status-action-bg);    color: var(--dgo-color-status-action-fg); }
.dgo-pill--draft     { background: var(--dgo-color-status-draft-bg);     color: var(--dgo-color-status-draft-fg); }
.dgo-pill--archived  { background: var(--dgo-color-status-archived-bg);  color: var(--dgo-color-status-archived-fg); }
.dgo-pill--escalated { background: var(--dgo-color-status-escalated-bg); color: var(--dgo-color-status-escalated-fg); }
.dgo-pill--info      { background: var(--dgo-color-info-subtle-bg);      color: var(--dgo-color-info-subtle-fg); }
.dgo-pill--success   { background: var(--dgo-color-success-subtle-bg);   color: var(--dgo-color-success-subtle-fg); }
.dgo-pill--warning   { background: var(--dgo-color-warning-subtle-bg);   color: var(--dgo-color-warning-subtle-fg); }
.dgo-pill--danger    { background: var(--dgo-color-danger-subtle-bg);    color: var(--dgo-color-danger-subtle-fg); }

/* Counter badge (numeric) */
.dgo-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: 18px; block-size: 18px; padding-inline: 5px;
  font-size: 11px; font-weight: var(--dgo-wt-700); line-height: 1;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}

/* Tag (square) */
.dgo-tag {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-tag-h);
  padding-inline: var(--dgo-s-2);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tag-radius);
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-color-border-default);
}

/* Chip (interactive tag with × close) */
.dgo-chip {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1_5);
  block-size: 28px;
  padding-inline-start: var(--dgo-s-3);
  padding-inline-end: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  transition: background var(--dgo-motion-state);
}
.dgo-chip__close {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 20px; block-size: 20px;
  border-radius: 50%;
  color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-chip__close:hover { background: color-mix(in srgb, var(--dgo-color-action-primary) 20%, transparent); }

/* ============================================================
   8 · AVATAR
   ============================================================ */
.dgo-avatar {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 36px; block-size: 36px;
  border-radius: 50%;
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  letter-spacing: var(--dgo-tr-tight);
  overflow: hidden;
  flex-shrink: 0;
}
.dgo-avatar--sm { inline-size: 24px; block-size: 24px; font-size: 11px; }
.dgo-avatar--lg { inline-size: 48px; block-size: 48px; font-size: var(--dgo-type-body-lg); }
.dgo-avatar--xl { inline-size: 72px; block-size: 72px; font-size: var(--dgo-type-h3); }
.dgo-avatar img { inline-size: 100%; block-size: 100%; object-fit: cover; }
.dgo-avatar-stack { display: inline-flex; }
.dgo-avatar-stack .dgo-avatar { box-shadow: 0 0 0 2px var(--dgo-color-surface-page); }
.dgo-avatar-stack .dgo-avatar + .dgo-avatar { margin-inline-start: -10px; }

/* ============================================================
   9 · CARD
   ============================================================ */
.dgo-card {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  transition: box-shadow var(--dgo-motion-state), border-color var(--dgo-motion-state), transform var(--dgo-motion-state);
}
.dgo-card--flat   { box-shadow: var(--dgo-elevation-flat); }
.dgo-card--raised { box-shadow: var(--dgo-elevation-card); }
.dgo-card--hoverable { cursor: pointer; }
.dgo-card--hoverable:hover {
  box-shadow: var(--dgo-card-shadow-hover);
  border-color: var(--dgo-color-border-strong);
}
.dgo-card--accent {
  border-inline-start: 4px solid var(--dgo-color-action-accent);
}
.dgo-card__header {
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--dgo-s-3);
  margin-block-end: var(--dgo-s-3);
}
.dgo-card__title {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h4);
  font-weight: var(--dgo-wt-700);
  line-height: var(--dgo-lh-120);
  margin: 0;
}
.dgo-card__sub { font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); margin: 2px 0 0; }
.dgo-card__footer {
  margin-block-start: var(--dgo-s-4);
  padding-block-start: var(--dgo-s-3);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; align-items: center; gap: var(--dgo-s-2);
}

/* Frame — large container shell */
.dgo-frame {
  background: var(--dgo-color-surface-page);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-frame);
  overflow: clip;
  box-shadow: var(--dgo-elevation-card);
}

/* ============================================================
   10 · ALERT / BANNER
   ============================================================ */
.dgo-alert {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-alert-pad);
  border: var(--dgo-alert-border-w) solid;
  border-radius: var(--dgo-alert-radius);
  font-size: var(--dgo-type-body);
  background: var(--dgo-color-surface-raised);
}
.dgo-alert__icon { flex-shrink: 0; margin-block-start: 2px; }
.dgo-alert__title { font-weight: var(--dgo-wt-600); margin-block-end: 2px; }
.dgo-alert__body  { color: var(--dgo-color-fg-default); }
.dgo-alert--info    { background: var(--dgo-color-info-subtle-bg);    color: var(--dgo-color-info-subtle-fg);    border-color: color-mix(in srgb, var(--dgo-color-info-subtle-fg) 30%, transparent); }
.dgo-alert--success { background: var(--dgo-color-success-subtle-bg); color: var(--dgo-color-success-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-success-subtle-fg) 30%, transparent); }
.dgo-alert--warning { background: var(--dgo-color-warning-subtle-bg); color: var(--dgo-color-warning-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-warning-subtle-fg) 30%, transparent); }
.dgo-alert--danger  { background: var(--dgo-color-danger-subtle-bg);  color: var(--dgo-color-danger-subtle-fg);  border-color: color-mix(in srgb, var(--dgo-color-danger-subtle-fg) 30%, transparent); }

/* Banner — full-width page-level */
.dgo-banner {
  display: flex; align-items: center; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-3) var(--dgo-s-5);
  background: var(--dgo-color-surface-brand);
  color: var(--dgo-color-fg-on-brand);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   11 · TOAST / SNACKBAR
   ============================================================ */
.dgo-toast-region {
  position: fixed;
  inset-block-end: var(--dgo-s-6);
  inset-inline-end: var(--dgo-s-6);
  display: flex; flex-direction: column; gap: var(--dgo-s-3);
  z-index: var(--dgo-z-toast);
  max-inline-size: 380px;
  pointer-events: none;
}
.dgo-toast {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  box-shadow: var(--dgo-elevation-overlay);
  pointer-events: auto;
  animation: dgo-toast-in var(--dgo-motion-enter);
}
@keyframes dgo-toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

/* ============================================================
   12 · MODAL / DRAWER
   ============================================================ */
.dgo-modal-backdrop {
  position: fixed; inset: 0;
  background: var(--dgo-color-surface-overlay);
  z-index: var(--dgo-z-modal);
  display: grid; place-items: center;
  padding: var(--dgo-s-4);
  animation: dgo-fade-in var(--dgo-motion-enter);
}
.dgo-modal {
  inline-size: 100%;
  max-inline-size: var(--dgo-modal-w);
  max-block-size: 90vh;
  display: flex; flex-direction: column;
  background: var(--dgo-color-surface-raised);
  border-radius: var(--dgo-modal-radius);
  box-shadow: var(--dgo-modal-shadow);
  overflow: clip;
  animation: dgo-modal-in var(--dgo-motion-enter);
}
.dgo-modal--lg { max-inline-size: var(--dgo-modal-w-lg); }
.dgo-modal__header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-5) var(--dgo-s-6);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-modal__title { font-size: var(--dgo-type-h3); font-weight: var(--dgo-wt-700); margin: 0; }
.dgo-modal__body { padding: var(--dgo-s-6); overflow-y: auto; }
.dgo-modal__footer {
  padding: var(--dgo-s-4) var(--dgo-s-6);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; justify-content: flex-end; gap: var(--dgo-s-2);
}
@keyframes dgo-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes dgo-modal-in { from { opacity: 0; transform: translateY(8px) scale(0.98); } to { opacity: 1; transform: none; } }

.dgo-drawer {
  position: fixed; inset-block: 0; inset-inline-end: 0;
  inline-size: var(--dgo-drawer-w); max-inline-size: 100vw;
  background: var(--dgo-color-surface-raised);
  box-shadow: var(--dgo-elevation-modal);
  display: flex; flex-direction: column;
  animation: dgo-drawer-in var(--dgo-motion-enter);
  z-index: var(--dgo-z-modal);
}
@keyframes dgo-drawer-in { from { transform: translateX(100%); } to { transform: none; } }
[dir="rtl"] .dgo-drawer { inset-inline-end: auto; inset-inline-start: 0; }

/* ============================================================
   13 · SIDEBAR
   ============================================================ */
.dgo-sidebar {
  display: flex; flex-direction: column; gap: var(--dgo-s-5);
  padding: var(--dgo-s-5) var(--dgo-s-3);
  background: var(--dgo-sidebar-bg);
  color: var(--dgo-sidebar-fg);
  block-size: 100vh;
  position: sticky;
  inset-block-start: 0;
}
.dgo-sidebar__brand { padding-inline: var(--dgo-s-2); padding-block-end: var(--dgo-s-4); border-block-end: 1px solid var(--dgo-color-border-on-brand); }
.dgo-sidebar__nav { display: flex; flex-direction: column; gap: 2px; flex: 1; }
.dgo-sidebar__group-label {
  font-size: 10px;
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-widest);
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
  padding-inline: var(--dgo-s-3);
  padding-block: var(--dgo-s-3) var(--dgo-s-1);
}

.dgo-sidebar__item {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-radius-control);
  color: rgba(255,255,255,0.78);
  text-decoration: none;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  transition: background var(--dgo-motion-state), color var(--dgo-motion-state);
  position: relative;
  min-block-size: 36px;
}
.dgo-sidebar__item:hover { color: #fff; background: rgba(255,255,255,0.06); }
.dgo-sidebar__item[aria-current="page"],
.dgo-sidebar__item--active {
  background: rgba(255,255,255,0.10);
  color: #fff;
}
.dgo-sidebar__item[aria-current="page"]::before,
.dgo-sidebar__item--active::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  inset-block: 8px;
  inline-size: 3px;
  background: var(--dgo-color-action-accent);
  border-radius: 2px;
}
.dgo-sidebar__count {
  margin-inline-start: auto;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: var(--dgo-r-pill);
  background: rgba(255,255,255,0.10);
}
.dgo-sidebar__footer {
  padding-block-start: var(--dgo-s-4);
  border-block-start: 1px solid var(--dgo-color-border-on-brand);
}

/* ============================================================
   14 · TOPBAR
   ============================================================ */
.dgo-topbar {
  display: flex; align-items: center; gap: var(--dgo-s-4);
  block-size: var(--dgo-topbar-h);
  padding-inline: var(--dgo-s-5);
  background: var(--dgo-topbar-bg);
  border-block-end: 1px solid var(--dgo-topbar-border);
  position: sticky; inset-block-start: 0;
  z-index: var(--dgo-z-sticky);
}

/* ============================================================
   15 · TABS
   ============================================================ */
.dgo-tabs { display: flex; flex-direction: column; gap: var(--dgo-s-5); }
.dgo-tabs__list {
  display: flex; gap: var(--dgo-s-1);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-tabs__tab {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  font-size: var(--dgo-type-body);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-muted);
  border: 0; background: transparent;
  border-block-end: var(--dgo-tabs-indicator-h) solid transparent;
  margin-block-end: -1px;
  cursor: pointer;
  transition: color var(--dgo-motion-state), border-color var(--dgo-motion-state);
}
.dgo-tabs__tab:hover { color: var(--dgo-color-fg-default); }
.dgo-tabs__tab[aria-selected="true"] {
  color: var(--dgo-color-action-primary);
  border-block-end-color: var(--dgo-tabs-indicator);
  font-weight: var(--dgo-wt-600);
}

/* ============================================================
   16 · BREADCRUMB
   ============================================================ */
.dgo-crumbs { display: flex; align-items: center; gap: var(--dgo-s-2); font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); }
.dgo-crumbs__sep { color: var(--dgo-color-fg-subtle); }
.dgo-crumbs a { color: var(--dgo-color-fg-muted); text-decoration: none; }
.dgo-crumbs a:hover { color: var(--dgo-color-action-primary); }
.dgo-crumbs__current { color: var(--dgo-color-fg-default); font-weight: var(--dgo-wt-600); }

/* ============================================================
   17 · STEPPER / PAGINATION
   ============================================================ */
.dgo-stepper { display: flex; align-items: center; gap: var(--dgo-s-3); }
.dgo-stepper__step {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  color: var(--dgo-color-fg-muted);
  font-size: var(--dgo-type-body-sm);
}
.dgo-stepper__bullet {
  inline-size: 28px; block-size: 28px;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-muted);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  border: 1px solid var(--dgo-color-border-default);
}
.dgo-stepper__step[data-state="current"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-color: var(--dgo-color-action-primary);
}
.dgo-stepper__step[data-state="done"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
  border-color: var(--dgo-color-action-accent);
}
.dgo-stepper__step[data-state="current"], .dgo-stepper__step[data-state="done"] { color: var(--dgo-color-fg-default); }
.dgo-stepper__line { flex: 1; block-size: 2px; background: var(--dgo-color-border-default); border-radius: 2px; }
.dgo-stepper__step[data-state="done"] + .dgo-stepper__line { background: var(--dgo-color-action-accent); }

.dgo-pagination { display: inline-flex; align-items: center; gap: var(--dgo-s-1); }
.dgo-pagination__btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: var(--dgo-pagination-h); block-size: var(--dgo-pagination-h);
  padding-inline: var(--dgo-s-2);
  border-radius: var(--dgo-pagination-radius);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-default);
  background: transparent;
  border: 1px solid transparent;
}
.dgo-pagination__btn:hover { background: var(--dgo-color-surface-sunken); }
.dgo-pagination__btn[aria-current="page"] {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-pagination__btn:disabled { color: var(--dgo-color-fg-disabled); cursor: not-allowed; }

/* ============================================================
   18 · TABLE / DATA GRID
   ============================================================ */
.dgo-table-wrap {
  border: 1px solid var(--dgo-table-border);
  border-radius: var(--dgo-radius-card);
  overflow: clip;
  background: var(--dgo-color-surface-raised);
}
.dgo-table {
  inline-size: 100%;
  border-collapse: collapse;
  font-size: var(--dgo-type-body-sm);
}
.dgo-table thead { background: var(--dgo-table-header-bg); }
.dgo-table th {
  text-align: start;
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-table-header-fg);
  border-block-end: 1px solid var(--dgo-table-border);
  white-space: nowrap;
}
.dgo-table td {
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  color: var(--dgo-color-fg-default);
  border-block-end: 1px solid var(--dgo-table-border);
  vertical-align: middle;
}
.dgo-table tbody tr:hover td { background: var(--dgo-table-row-hover); }
.dgo-table tbody tr:last-child td { border-block-end: 0; }
.dgo-table--striped tbody tr:nth-child(even) td { background: var(--dgo-color-surface-sunken); }

.dgo-table__num { text-align: end; font-variant-numeric: tabular-nums; }
.dgo-table__sort {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  color: inherit; cursor: pointer;
}

/* ============================================================
   19 · TOOLTIP / POPOVER
   ============================================================ */
.dgo-tooltip {
  display: inline-block;
  padding: 6px 10px;
  background: var(--dgo-tooltip-bg);
  color: var(--dgo-tooltip-fg);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tooltip-radius);
  box-shadow: var(--dgo-shadow-3);
  max-inline-size: 280px;
}
.dgo-popover {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-popover-radius);
  padding: var(--dgo-popover-pad);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 220px;
}

/* ============================================================
   20 · MENU / DROPDOWN
   ============================================================ */
.dgo-menu {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  padding: var(--dgo-s-1);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 200px;
}
.dgo-menu__item {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-r-6);
  font-size: var(--dgo-type-body-sm);
  color: var(--dgo-color-fg-default);
  text-decoration: none;
  cursor: pointer;
}
.dgo-menu__item:hover, .dgo-menu__item:focus-visible {
  background: var(--dgo-color-surface-sunken);
  outline: none;
}
.dgo-menu__item--danger { color: var(--dgo-color-action-danger); }
.dgo-menu__item--danger:hover { background: var(--dgo-color-danger-subtle-bg); }
.dgo-menu__sep { block-size: 1px; background: var(--dgo-color-border-default); margin: var(--dgo-s-1) 0; }
.dgo-menu__label {
  font-size: var(--dgo-type-caption);
  text-transform: uppercase;
  letter-spacing: var(--dgo-tr-wide);
  color: var(--dgo-color-fg-muted);
  padding: var(--dgo-s-2) var(--dgo-s-3) var(--dgo-s-1);
}

/* ============================================================
   21 · EMPTY / ERROR / ONBOARDING STATE
   ============================================================ */
.dgo-empty {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: var(--dgo-s-3);
  padding: var(--dgo-s-12) var(--dgo-s-6);
  color: var(--dgo-color-fg-muted);
}
.dgo-empty__title { font-size: var(--dgo-type-h4); font-weight: var(--dgo-wt-700); color: var(--dgo-color-fg-default); }
.dgo-empty__body { max-inline-size: 42ch; }

/* ============================================================
   22 · PROGRESS / SPINNER
   ============================================================ */
.dgo-progress {
  inline-size: 100%;
  block-size: var(--dgo-progress-h);
  background: var(--dgo-progress-track);
  border-radius: var(--dgo-r-pill);
  overflow: hidden;
}
.dgo-progress__fill {
  block-size: 100%;
  background: var(--dgo-progress-fill);
  border-radius: inherit;
  transition: inline-size var(--dgo-motion-state);
}
.dgo-progress--accent .dgo-progress__fill { background: var(--dgo-color-action-accent); }

.dgo-progress-ring {
  inline-size: 56px; block-size: 56px;
  display: inline-grid; place-items: center;
  --_p: 0; /* @kind other */
  background:
    conic-gradient(var(--dgo-color-action-primary) calc(var(--_p) * 1%), var(--dgo-progress-track) 0);
  border-radius: 50%;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-700);
  color: var(--dgo-color-fg-default);
  position: relative;
}
.dgo-progress-ring::before {
  content: ""; position: absolute; inset: 5px;
  background: var(--dgo-color-surface-page);
  border-radius: 50%;
}
.dgo-progress-ring > span { position: relative; }

.dgo-spinner {
  inline-size: 24px; block-size: 24px;
  border: 2.5px solid var(--dgo-color-surface-sunken);
  border-block-start-color: var(--dgo-color-action-primary);
  border-radius: 50%;
  animation: dgo-spin 0.8s linear infinite;
}

/* ============================================================
   23 · SKELETON
   ============================================================ */
.dgo-skeleton {
  display: block;
  background:
    linear-gradient(90deg,
      var(--dgo-skeleton-base) 0%,
      var(--dgo-skeleton-shine) 50%,
      var(--dgo-skeleton-base) 100%);
  background-size: 200% 100%;
  border-radius: var(--dgo-r-6);
  animation: dgo-skeleton 1.4s linear infinite;
  min-block-size: 12px;
}
@keyframes dgo-skeleton {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
.dgo-skeleton--circle { border-radius: 50%; }

/* ============================================================
   24 · METRIC / STAT TILE
   ============================================================ */
.dgo-metric {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  display: flex; flex-direction: column; gap: var(--dgo-s-2);
}
.dgo-metric__label {
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-color-fg-muted);
}
.dgo-metric__value {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h1);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-tightest);
  line-height: var(--dgo-lh-110);
  font-variant-numeric: tabular-nums;
  color: var(--dgo-color-fg-strong);
}
.dgo-metric__delta {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
}
.dgo-metric__delta--up { color: var(--dgo-color-success-subtle-fg); }
.dgo-metric__delta--down { color: var(--dgo-color-danger-subtle-fg); }

/* ============================================================
   25 · KBD / CODE
   ============================================================ */
.dgo-kbd {
  display: inline-flex; align-items: center;
  min-inline-size: 22px; block-size: 22px;
  padding-inline: 6px;
  font-family: var(--dgo-family-mono);
  font-size: 11px;
  font-weight: var(--dgo-wt-600);
  background: var(--dgo-kbd-bg);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-kbd-border);
  border-block-end-width: 2px;
  border-radius: var(--dgo-r-4);
}

.dgo-code-block {
  display: block;
  font-family: var(--dgo-family-mono);
  font-size: var(--dgo-type-body-sm);
  line-height: var(--dgo-lh-150);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
  padding: var(--dgo-s-4);
  border-radius: var(--dgo-radius-card);
  border: 1px solid var(--dgo-color-border-default);
  overflow-x: auto;
  white-space: pre;
}

.dgo-inline-code {
  font-family: var(--dgo-family-mono);
  font-size: 0.88em;
  padding: 2px 6px;
  border-radius: var(--dgo-r-4);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
}

/* ============================================================
   26 · FILTER BAR / BULK-ACTION BAR
   ============================================================ */
.dgo-filter-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3); flex-wrap: wrap;
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar .dgo-btn--ghost { color: var(--dgo-color-fg-on-brand); }
.dgo-bulk-bar .dgo-btn--ghost:hover { background: rgba(255,255,255,0.12); }

/* ============================================================
   Utilities
   ============================================================ */
.dgo-divider { block-size: 1px; background: var(--dgo-color-border-default); border: 0; margin-block: var(--dgo-s-5); }

/* Tabular numerals helper */
.dgo-tnum { font-variant-numeric: tabular-nums; }

/* ============================================================
   DGO Design System v2.0 — Component Library
   ============================================================
   Organised by family; BEM under `.dgo-` namespace.
   Every value references a token — no hard-coded hex/px/ms.
   ------------------------------------------------------------
   Index:
   1.  Button             7.  Pill / Badge / Tag      13. Sidebar
   2.  Input / Textarea   8.  Avatar                  14. Topbar
   3.  Select             9.  Card                    15. Tabs
   4.  Checkbox / Radio   10. Alert / Banner          16. Breadcrumb
   5.  Switch             11. Toast                   17. Stepper / Pagination
   6.  Search             12. Modal / Drawer          18. Table / Data grid
                          19. Tooltip / Popover       20. Menu / Dropdown
                          21. Empty / Error state     22. Progress / Spinner
                          23. Skeleton                24. Metric / Stat
                          25. Kbd / Code              26. Chip / Filter bar
   ============================================================ */

@layer dgo-reset, dgo-base, dgo-component, dgo-utility;

/* ============================================================
   DGO · Components Index (v2.1 split)
   ------------------------------------------------------------
   This file replaces the single-file components.css. The cascade
   layer order is declared once above; each family is @imported
   below into the dgo-component layer in the original v2.0 order.
   Authors include only this file; tree-shake by removing imports
   you don't need.
   ============================================================ */

@import url("./button.css") layer(dgo-component);
@import url("./input.css") layer(dgo-component);
@import url("./select.css") layer(dgo-component);
@import url("./checkbox-radio.css") layer(dgo-component);
@import url("./switch.css") layer(dgo-component);
@import url("./search.css") layer(dgo-component);
@import url("./badge.css") layer(dgo-component);
@import url("./avatar.css") layer(dgo-component);
@import url("./card.css") layer(dgo-component);
@import url("./alert.css") layer(dgo-component);
@import url("./toast.css") layer(dgo-component);
@import url("./modal.css") layer(dgo-component);
@import url("./sidebar.css") layer(dgo-component);
@import url("./topbar.css") layer(dgo-component);
@import url("./tabs.css") layer(dgo-component);
@import url("./breadcrumb.css") layer(dgo-component);
@import url("./stepper-pagination.css") layer(dgo-component);
@import url("./table.css") layer(dgo-component);
@import url("./tooltip-popover.css") layer(dgo-component);
@import url("./menu.css") layer(dgo-component);
@import url("./empty-state.css") layer(dgo-component);
@import url("./progress.css") layer(dgo-component);
@import url("./skeleton.css") layer(dgo-component);
@import url("./metric.css") layer(dgo-component);
@import url("./kbd-code.css") layer(dgo-component);
@import url("./filter-bar.css") layer(dgo-component);
@import url("./_utilities.css") layer(dgo-component);

/* ------------------------------------------------------------
   v2.1 worked-example component (spec only, no CSS shipped):
   see docs/components/command-palette.md
   ------------------------------------------------------------ */

/* ============================================================
   DGO · Alert & Banner
   ------------------------------------------------------------
   Inline informational, success, warning, and danger messaging.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   10 · ALERT / BANNER
   ============================================================ */
.dgo-alert {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-alert-pad);
  border: var(--dgo-alert-border-w) solid;
  border-radius: var(--dgo-alert-radius);
  font-size: var(--dgo-type-body);
  background: var(--dgo-color-surface-raised);
}
.dgo-alert__icon { flex-shrink: 0; margin-block-start: 2px; }
.dgo-alert__title { font-weight: var(--dgo-wt-600); margin-block-end: 2px; }
.dgo-alert__body  { color: var(--dgo-color-fg-default); }
.dgo-alert--info    { background: var(--dgo-color-info-subtle-bg);    color: var(--dgo-color-info-subtle-fg);    border-color: color-mix(in srgb, var(--dgo-color-info-subtle-fg) 30%, transparent); }
.dgo-alert--success { background: var(--dgo-color-success-subtle-bg); color: var(--dgo-color-success-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-success-subtle-fg) 30%, transparent); }
.dgo-alert--warning { background: var(--dgo-color-warning-subtle-bg); color: var(--dgo-color-warning-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-warning-subtle-fg) 30%, transparent); }
.dgo-alert--danger  { background: var(--dgo-color-danger-subtle-bg);  color: var(--dgo-color-danger-subtle-fg);  border-color: color-mix(in srgb, var(--dgo-color-danger-subtle-fg) 30%, transparent); }

/* Banner — full-width page-level */
.dgo-banner {
  display: flex; align-items: center; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-3) var(--dgo-s-5);
  background: var(--dgo-color-surface-brand);
  color: var(--dgo-color-fg-on-brand);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   DGO · Avatar
   ------------------------------------------------------------
   Person and entity representation; supports image, initials, stack.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   8 · AVATAR
   ============================================================ */
.dgo-avatar {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 36px; block-size: 36px;
  border-radius: 50%;
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  letter-spacing: var(--dgo-tr-tight);
  overflow: hidden;
  flex-shrink: 0;
}
.dgo-avatar--sm { inline-size: 24px; block-size: 24px; font-size: 11px; }
.dgo-avatar--lg { inline-size: 48px; block-size: 48px; font-size: var(--dgo-type-body-lg); }
.dgo-avatar--xl { inline-size: 72px; block-size: 72px; font-size: var(--dgo-type-h3); }
.dgo-avatar img { inline-size: 100%; block-size: 100%; object-fit: cover; }
.dgo-avatar-stack { display: inline-flex; }
.dgo-avatar-stack .dgo-avatar { box-shadow: 0 0 0 2px var(--dgo-color-surface-page); }
.dgo-avatar-stack .dgo-avatar + .dgo-avatar { margin-inline-start: -10px; }

/* ============================================================
   DGO · Pill / Badge / Tag / Chip
   ------------------------------------------------------------
   Inline status, count, label, and filter pellets.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   7 · PILL / BADGE / TAG / CHIP
   ============================================================ */
.dgo-pill {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-badge-h);
  padding-inline: var(--dgo-badge-px);
  font-size: var(--dgo-badge-fs);
  font-weight: var(--dgo-badge-fw);
  line-height: 1;
  border-radius: var(--dgo-badge-radius);
  white-space: nowrap;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
}
.dgo-pill__dot { inline-size: 6px; block-size: 6px; border-radius: 50%; background: currentColor; }

.dgo-pill--pending   { background: var(--dgo-color-status-pending-bg);   color: var(--dgo-color-status-pending-fg); }
.dgo-pill--routed    { background: var(--dgo-color-status-routed-bg);    color: var(--dgo-color-status-routed-fg); }
.dgo-pill--replied   { background: var(--dgo-color-status-replied-bg);   color: var(--dgo-color-status-replied-fg); }
.dgo-pill--action    { background: var(--dgo-color-status-action-bg);    color: var(--dgo-color-status-action-fg); }
.dgo-pill--draft     { background: var(--dgo-color-status-draft-bg);     color: var(--dgo-color-status-draft-fg); }
.dgo-pill--archived  { background: var(--dgo-color-status-archived-bg);  color: var(--dgo-color-status-archived-fg); }
.dgo-pill--escalated { background: var(--dgo-color-status-escalated-bg); color: var(--dgo-color-status-escalated-fg); }
.dgo-pill--info      { background: var(--dgo-color-info-subtle-bg);      color: var(--dgo-color-info-subtle-fg); }
.dgo-pill--success   { background: var(--dgo-color-success-subtle-bg);   color: var(--dgo-color-success-subtle-fg); }
.dgo-pill--warning   { background: var(--dgo-color-warning-subtle-bg);   color: var(--dgo-color-warning-subtle-fg); }
.dgo-pill--danger    { background: var(--dgo-color-danger-subtle-bg);    color: var(--dgo-color-danger-subtle-fg); }

/* Counter badge (numeric) */
.dgo-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: 18px; block-size: 18px; padding-inline: 5px;
  font-size: 11px; font-weight: var(--dgo-wt-700); line-height: 1;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}

/* Tag (square) */
.dgo-tag {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-tag-h);
  padding-inline: var(--dgo-s-2);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tag-radius);
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-color-border-default);
}

/* Chip (interactive tag with × close) */
.dgo-chip {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1_5);
  block-size: 28px;
  padding-inline-start: var(--dgo-s-3);
  padding-inline-end: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  transition: background var(--dgo-motion-state);
}
.dgo-chip__close {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 20px; block-size: 20px;
  border-radius: 50%;
  color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-chip__close:hover { background: color-mix(in srgb, var(--dgo-color-action-primary) 20%, transparent); }

/* ============================================================
   DGO · Breadcrumb
   ------------------------------------------------------------
   Hierarchical location trail.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   16 · BREADCRUMB
   ============================================================ */
.dgo-crumbs { display: flex; align-items: center; gap: var(--dgo-s-2); font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); }
.dgo-crumbs__sep { color: var(--dgo-color-fg-subtle); }
.dgo-crumbs a { color: var(--dgo-color-fg-muted); text-decoration: none; }
.dgo-crumbs a:hover { color: var(--dgo-color-action-primary); }
.dgo-crumbs__current { color: var(--dgo-color-fg-default); font-weight: var(--dgo-wt-600); }

/* ============================================================
   DGO · Button
   ------------------------------------------------------------
   Action triggers (primary/secondary/tertiary/ghost/danger × sm/md/lg + button-group).

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   1 · BUTTON
   ============================================================
   States: default · hover · focus-visible · active · disabled · loading
   Variants: primary · secondary · tertiary · ghost · danger
   Sizes: sm · md · lg
   ============================================================ */
.dgo-btn {
  --_h: var(--dgo-btn-h-md);
  --_px: var(--dgo-btn-px-md);
  --_fs: var(--dgo-type-body);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--dgo-s-2);
  block-size: var(--_h);
  padding-inline: var(--_px);
  font-family: var(--dgo-family-sans);
  font-size: var(--_fs);
  font-weight: var(--dgo-btn-fw);
  line-height: 1;
  border: 1px solid transparent;
  border-radius: var(--dgo-btn-radius);
  cursor: pointer;
  user-select: none;
  text-decoration: none;
  white-space: nowrap;
  transition:
    background-color var(--dgo-motion-state),
    border-color var(--dgo-motion-state),
    color var(--dgo-motion-state),
    box-shadow var(--dgo-motion-state),
    transform var(--dgo-dur-instant) var(--dgo-ease-sharp);
  min-inline-size: var(--_h); /* hit area floor */
}

.dgo-btn:focus-visible { box-shadow: var(--dgo-focus-ring); }
.dgo-btn:active:not(:disabled) { transform: translateY(1px); }
.dgo-btn:disabled,
.dgo-btn[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
  pointer-events: none;
}

.dgo-btn--sm { --_h: var(--dgo-btn-h-sm); --_px: var(--dgo-btn-px-sm); --_fs: var(--dgo-type-body-sm); }
.dgo-btn--lg { --_h: var(--dgo-btn-h-lg); --_px: var(--dgo-btn-px-lg); --_fs: var(--dgo-type-body-lg); }
.dgo-btn--block { inline-size: 100%; }

/* Primary */
.dgo-btn--primary {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--primary:hover:not(:disabled) { background: var(--dgo-color-action-primary-hover); box-shadow: var(--dgo-shadow-2); }
.dgo-btn--primary:active:not(:disabled) { background: var(--dgo-color-action-primary-press); }

/* Secondary — outline */
.dgo-btn--secondary {
  background: transparent;
  color: var(--dgo-color-action-primary);
  border-color: var(--dgo-color-border-strong);
}
.dgo-btn--secondary:hover:not(:disabled) {
  border-color: var(--dgo-color-action-primary);
  background: var(--dgo-color-action-secondary-hover);
}
.dgo-btn--secondary:active:not(:disabled) { background: var(--dgo-color-action-secondary-press); }

/* Tertiary — text + subtle hover */
.dgo-btn--tertiary,
.dgo-btn--ghost {
  background: transparent;
  color: var(--dgo-color-action-primary);
}
.dgo-btn--tertiary:hover:not(:disabled),
.dgo-btn--ghost:hover:not(:disabled) { background: var(--dgo-color-action-secondary-hover); }

/* Danger */
.dgo-btn--danger {
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--danger:hover:not(:disabled) { background: var(--dgo-color-action-danger-hover); }

/* Accent */
.dgo-btn--accent {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
}
.dgo-btn--accent:hover:not(:disabled) { background: var(--dgo-color-action-accent-hover); }

/* Icon button */
.dgo-btn--icon { padding-inline: 0; inline-size: var(--_h); }

/* Loading */
.dgo-btn[data-loading="true"] { color: transparent; position: relative; }
.dgo-btn[data-loading="true"]::after {
  content: "";
  position: absolute;
  inline-size: 1em; block-size: 1em;
  border: 2px solid currentColor;
  border-block-start-color: transparent;
  border-radius: 50%;
  color: var(--dgo-color-fg-on-brand);
  animation: dgo-spin 0.6s linear infinite;
}
.dgo-btn--secondary[data-loading="true"]::after,
.dgo-btn--tertiary[data-loading="true"]::after,
.dgo-btn--ghost[data-loading="true"]::after { color: var(--dgo-color-action-primary); }

@keyframes dgo-spin { to { transform: rotate(360deg); } }

/* Button group */
.dgo-btn-group { display: inline-flex; }
.dgo-btn-group .dgo-btn {
  border-radius: 0;
}
.dgo-btn-group .dgo-btn:first-child { border-start-start-radius: var(--dgo-btn-radius); border-end-start-radius: var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn:last-child  { border-start-end-radius:   var(--dgo-btn-radius); border-end-end-radius:   var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn + .dgo-btn { margin-inline-start: -1px; }

/* ============================================================
   DGO · Card
   ------------------------------------------------------------
   White surface container; header / body / footer.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   9 · CARD
   ============================================================ */
.dgo-card {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  transition: box-shadow var(--dgo-motion-state), border-color var(--dgo-motion-state), transform var(--dgo-motion-state);
}
.dgo-card--flat   { box-shadow: var(--dgo-elevation-flat); }
.dgo-card--raised { box-shadow: var(--dgo-elevation-card); }
.dgo-card--hoverable { cursor: pointer; }
.dgo-card--hoverable:hover {
  box-shadow: var(--dgo-card-shadow-hover);
  border-color: var(--dgo-color-border-strong);
}
.dgo-card--accent {
  border-inline-start: 4px solid var(--dgo-color-action-accent);
}
.dgo-card__header {
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--dgo-s-3);
  margin-block-end: var(--dgo-s-3);
}
.dgo-card__title {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h4);
  font-weight: var(--dgo-wt-700);
  line-height: var(--dgo-lh-120);
  margin: 0;
}
.dgo-card__sub { font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); margin: 2px 0 0; }
.dgo-card__footer {
  margin-block-start: var(--dgo-s-4);
  padding-block-start: var(--dgo-s-3);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; align-items: center; gap: var(--dgo-s-2);
}

/* Frame — large container shell */
.dgo-frame {
  background: var(--dgo-color-surface-page);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-frame);
  overflow: clip;
  box-shadow: var(--dgo-elevation-card);
}

/* ============================================================
   DGO · Checkbox & Radio
   ------------------------------------------------------------
   Boolean and single-choice controls; shares the field reset.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   4 · CHECKBOX / RADIO
   ============================================================ */
.dgo-check, .dgo-radio {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  cursor: pointer; user-select: none;
  font-size: var(--dgo-type-body);
}
.dgo-check input[type="checkbox"],
.dgo-radio input[type="radio"] {
  inline-size: 18px; block-size: 18px;
  margin: 0;
  accent-color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-check input:focus-visible,
.dgo-radio input:focus-visible {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   DGO · Command Palette  (v2.1)
   ------------------------------------------------------------
   Keyboard-first launcher. WAI-ARIA APG 1.2 combobox-with-
   aria-activedescendant pattern. Tab closes the palette (see
   docs/components/command-palette.md §9).

   Layer:        dgo-component
   Namespace:    .dgo-cmdk* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css      (--dgo-cmdk-* block)
                 tokens/tokens.density.css
                 styles/base.css                  (dgo-visually-hidden,
                                                   focus-ring var)
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ------------------------------------------------------------
   Backdrop + state machine
   ------------------------------------------------------------ */
.dgo-cmdk-backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--dgo-cmdk-z, var(--dgo-z-modal));
  display: grid;
  place-items: start center;
  padding-block-start: 14vh;
  padding-inline: var(--dgo-s-4);
  background: var(--dgo-cmdk-backdrop-bg, var(--dgo-color-surface-overlay));
  animation: dgo-fade-in var(--dgo-motion-enter);
}
.dgo-cmdk-backdrop[data-state="closed"] { display: none; }
.dgo-cmdk-backdrop[data-state="closing"] { animation: dgo-fade-out var(--dgo-motion-exit) forwards; }

/* ------------------------------------------------------------
   Dialog
   ------------------------------------------------------------ */
.dgo-cmdk {
  inline-size: 100%;
  max-inline-size: var(--dgo-cmdk-w, clamp(320px, 90vw, 640px));
  max-block-size: min(80vh, 720px);
  display: flex;
  flex-direction: column;
  background: var(--dgo-cmdk-bg, var(--dgo-color-surface-raised));
  border: 1px solid var(--dgo-cmdk-border, var(--dgo-color-border-default));
  border-radius: var(--dgo-cmdk-radius, var(--dgo-r-10));
  box-shadow: var(--dgo-cmdk-shadow, var(--dgo-elevation-modal, var(--dgo-shadow-5)));
  overflow: clip;
  animation: dgo-cmdk-in var(--dgo-motion-enter);
}
.dgo-cmdk-backdrop[data-state="closing"] .dgo-cmdk {
  animation: dgo-cmdk-out var(--dgo-motion-exit) forwards;
}

/* Inline variant — no backdrop, no focus trap, no animation */
.dgo-cmdk--inline {
  position: relative;
  animation: none;
  max-block-size: none;
}

/* ------------------------------------------------------------
   Search row
   ------------------------------------------------------------ */
.dgo-cmdk__search {
  display: flex;
  align-items: center;
  gap: var(--dgo-s-3);
  padding-inline: var(--dgo-s-4);
  block-size: var(--dgo-cmdk-input-h, 48px);
  border-block-end: 1px solid var(--dgo-color-border-default);
  background: var(--dgo-cmdk-input-bg, transparent);
}
.dgo-cmdk__search-icon {
  flex: none;
  inline-size: 20px; block-size: 20px;
  color: var(--dgo-color-fg-muted);
  fill: none; stroke: currentColor; stroke-width: 1.75;
}
.dgo-cmdk__input {
  flex: 1 1 auto;
  min-inline-size: 0;
  block-size: 100%;
  border: 0;
  outline: 0;            /* the focus surface is the active descendant — see §10 */
  background: transparent;
  color: var(--dgo-color-fg-strong);
  font-family: var(--dgo-family-sans, inherit);
  font-size: var(--dgo-cmdk-input-fs, var(--dgo-type-body-lg));
  line-height: var(--dgo-lh-130, 1.3);
  caret-color: var(--dgo-color-action-primary);
}
.dgo-cmdk__input::placeholder {
  color: var(--dgo-color-fg-subtle);
  font-weight: var(--dgo-wt-400);
}
.dgo-cmdk__input::-webkit-search-cancel-button { display: none; }
.dgo-cmdk__hint {
  flex: none;
  font-size: var(--dgo-size-12, 12px);
  color: var(--dgo-color-fg-subtle);
  font-family: var(--dgo-family-mono, ui-monospace, monospace);
  letter-spacing: var(--dgo-tr-normal);
  user-select: none;
}

/* ------------------------------------------------------------
   Listbox
   ------------------------------------------------------------ */
.dgo-cmdk__listbox {
  list-style: none;
  margin: 0;
  padding: var(--dgo-cmdk-pad, var(--dgo-s-2));
  overflow-y: auto;
  max-block-size: 40vh;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--dgo-color-border-strong) transparent;
}
.dgo-cmdk--inline .dgo-cmdk__listbox { max-block-size: none; }
.dgo-cmdk__listbox::-webkit-scrollbar { inline-size: 8px; }
.dgo-cmdk__listbox::-webkit-scrollbar-thumb {
  background: var(--dgo-color-border-strong);
  border-radius: 999px;
}

/* Group */
.dgo-cmdk__group { list-style: none; padding: 0; margin: 0; }
.dgo-cmdk__group + .dgo-cmdk__group { margin-block-start: var(--dgo-s-2); }
.dgo-cmdk__group > ul { list-style: none; padding: 0; margin: 0; }
.dgo-cmdk__group-label {
  font-family: var(--dgo-family-sans, inherit);
  font-size: var(--dgo-cmdk-group-label-fs, var(--dgo-size-12));
  font-weight: var(--dgo-wt-600);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--dgo-cmdk-group-label-fg, var(--dgo-color-fg-muted));
  padding-inline: var(--dgo-cmdk-item-pad, var(--dgo-s-3));
  padding-block: var(--dgo-s-2);
  margin: 0;
}

/* Item */
.dgo-cmdk__item {
  display: flex;
  align-items: center;
  gap: var(--dgo-s-3);
  min-block-size: var(--dgo-cmdk-item-h, 44px);
  padding-inline: var(--dgo-cmdk-item-pad, var(--dgo-s-3));
  padding-block: var(--dgo-s-2);
  border-radius: var(--dgo-cmdk-item-radius, var(--dgo-r-4));
  color: var(--dgo-color-fg-strong);
  font-size: var(--dgo-cmdk-item-fs, var(--dgo-type-body, var(--dgo-size-14)));
  cursor: pointer;
  user-select: none;
  background: var(--dgo-cmdk-item-bg, transparent);
  transition: background var(--dgo-motion-state, var(--dgo-dur-fast) var(--dgo-ease-standard));
}
.dgo-cmdk__item:hover { background: var(--dgo-color-surface-muted, var(--dgo-color-fg-on-accent)); }
.dgo-cmdk__item[aria-selected="true"] {
  background: var(--dgo-cmdk-item-bg-active, var(--dgo-color-action-primary-soft, var(--dgo-green-100)));
  color: var(--dgo-cmdk-item-fg-active, var(--dgo-color-fg-strong));
}
.dgo-cmdk__item[aria-selected="true"] .dgo-cmdk__item-icon { color: var(--dgo-color-action-primary); }
.dgo-cmdk__item[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
  pointer-events: none;
}
.dgo-cmdk__item:active { transform: scale(0.99); transition-duration: var(--dgo-dur-instant, 50ms); }

.dgo-cmdk__item-icon {
  flex: none;
  inline-size: 18px; block-size: 18px;
  color: var(--dgo-color-fg-muted);
  fill: none; stroke: currentColor; stroke-width: 1.75;
}
.dgo-cmdk__item-label {
  flex: 1 1 auto;
  min-inline-size: 0;
  font-weight: var(--dgo-wt-500);
  text-wrap: pretty;
  line-height: var(--dgo-lh-150, 1.5);
}
.dgo-cmdk__item-label mark {
  background: transparent;
  color: var(--dgo-color-action-primary);
  font-weight: var(--dgo-wt-700);
  padding: 0;
}
.dgo-cmdk__item-meta {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: var(--dgo-s-1, 4px);
  color: var(--dgo-cmdk-meta-fg, var(--dgo-color-fg-muted));
  font-size: var(--dgo-size-12, 12px);
}

/* Empty + footer */
.dgo-cmdk__empty {
  padding: var(--dgo-s-6) var(--dgo-s-4);
  text-align: center;
  color: var(--dgo-color-fg-muted);
  font-size: var(--dgo-type-body, var(--dgo-size-14));
}
.dgo-cmdk__empty strong {
  display: block;
  color: var(--dgo-color-fg-strong);
  font-weight: var(--dgo-wt-600);
  margin-block-end: var(--dgo-s-1, 4px);
}
.dgo-cmdk__footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-4);
  border-block-start: 1px solid var(--dgo-color-border-default);
  background: var(--dgo-color-surface-muted, transparent);
  font-size: var(--dgo-size-12, 12px);
  color: var(--dgo-color-fg-muted);
}
.dgo-cmdk__footer-hint { display: inline-flex; gap: var(--dgo-s-2); align-items: center; flex-wrap: wrap; }
.dgo-cmdk__footer-brand {
  font-family: var(--dgo-family-sans, inherit);
  font-weight: var(--dgo-wt-600);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--dgo-color-fg-subtle);
  font-size: 10px;
}

/* ------------------------------------------------------------
   Loading + error
   ------------------------------------------------------------ */
.dgo-cmdk[data-loading="true"] .dgo-cmdk__listbox { pointer-events: none; }
.dgo-cmdk__loading-row {
  display: block;
  block-size: var(--dgo-cmdk-item-h, 44px);
  margin: var(--dgo-s-1, 4px) 0;
  border-radius: var(--dgo-cmdk-item-radius, var(--dgo-r-4));
}
.dgo-cmdk[data-error="true"] .dgo-cmdk__listbox { display: none; }
.dgo-cmdk__error {
  padding: var(--dgo-s-4);
}

/* ------------------------------------------------------------
   Keyframes
   ------------------------------------------------------------ */
@keyframes dgo-cmdk-in {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes dgo-cmdk-out {
  from { opacity: 1; transform: translateY(0) scale(1); }
  to   { opacity: 0; transform: translateY(-8px) scale(0.98); }
}
@keyframes dgo-fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}

/* ------------------------------------------------------------
   Density
   The compact rebinds of --dgo-cmdk-input-h / -item-h / -item-pad
   live in tokens/tokens.density.css under the [data-density="compact"]
   root scope, so they register as proper density-scoped tokens
   (custom properties belong on a :root / [data-*] scope, not a
   component selector).
   ------------------------------------------------------------ */

/* ------------------------------------------------------------
   Theme overrides — high-contrast
   ------------------------------------------------------------ */
[data-theme="hc"] .dgo-cmdk {
  border-width: 2px;
  border-color: var(--dgo-color-fg-strong);
}
[data-theme="hc"] .dgo-cmdk__input {
  border-block-end: 2px solid var(--dgo-color-fg-strong);
}
[data-theme="hc"] .dgo-cmdk__item[aria-selected="true"] {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-accent, #fff);
  outline: 2px solid var(--dgo-color-fg-strong);
  outline-offset: -2px;
}

/* ------------------------------------------------------------
   Forced-colours fallback (Windows HC, OS-level)
   ------------------------------------------------------------ */
@media (forced-colors: active) {
  .dgo-cmdk {
    border: 2px solid CanvasText;
    box-shadow: none;
    background: Canvas;
  }
  .dgo-cmdk__search { border-block-end: 2px solid CanvasText; }
  .dgo-cmdk__input { color: CanvasText; }
  .dgo-cmdk__item[aria-selected="true"] {
    background: Highlight;
    color: HighlightText;
    forced-color-adjust: none;
  }
  .dgo-cmdk__item[aria-selected="true"] .dgo-cmdk__item-icon { color: HighlightText; }
  .dgo-cmdk__item-meta { color: GrayText; }
}

/* ------------------------------------------------------------
   Reduced-motion fallback
   ------------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  .dgo-cmdk,
  .dgo-cmdk-backdrop,
  .dgo-cmdk-backdrop[data-state="closing"] .dgo-cmdk,
  .dgo-cmdk-backdrop[data-state="closing"] {
    animation: none;
  }
  .dgo-cmdk__item { transition: none; }
  .dgo-cmdk__item:active { transform: none; }
}

/* ------------------------------------------------------------
   RTL — the dialog is symmetric; nothing to flip except the
   item chevron used by submenu-bearing rows.
   ------------------------------------------------------------ */
[dir="rtl"] .dgo-cmdk__item-chevron[data-rtl-flip] { transform: scaleX(-1); }

/* ============================================================
   DGO · Empty, Error & Onboarding State
   ------------------------------------------------------------
   Full-region placeholders for absent data, error recovery, and first-run guidance.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   21 · EMPTY / ERROR / ONBOARDING STATE
   ============================================================ */
.dgo-empty {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: var(--dgo-s-3);
  padding: var(--dgo-s-12) var(--dgo-s-6);
  color: var(--dgo-color-fg-muted);
}
.dgo-empty__title { font-size: var(--dgo-type-h4); font-weight: var(--dgo-wt-700); color: var(--dgo-color-fg-default); }
.dgo-empty__body { max-inline-size: 42ch; }

/* ============================================================
   DGO · Filter Bar & Bulk-Action Bar
   ------------------------------------------------------------
   Toolbar surfaces above tables and lists.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   26 · FILTER BAR / BULK-ACTION BAR
   ============================================================ */
.dgo-filter-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3); flex-wrap: wrap;
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar .dgo-btn--ghost { color: var(--dgo-color-fg-on-brand); }
.dgo-bulk-bar .dgo-btn--ghost:hover { background: rgba(255,255,255,0.12); }

/* ============================================================
   DGO · Input & Textarea
   ------------------------------------------------------------
   Single-line and multi-line text controls with label, help, and error affordances.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   2 · INPUT / TEXTAREA
   ============================================================ */
.dgo-input,
.dgo-textarea,
.dgo-select__field {
  display: block;
  inline-size: 100%;
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-input-px);
  padding-block: 0;
  font-family: var(--dgo-family-sans);
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  background: var(--dgo-input-bg);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  transition: border-color var(--dgo-motion-state), box-shadow var(--dgo-motion-state), background-color var(--dgo-motion-state);
}
.dgo-input::placeholder,
.dgo-textarea::placeholder { color: var(--dgo-input-placeholder); }

.dgo-input:hover:not(:disabled),
.dgo-textarea:hover:not(:disabled),
.dgo-select__field:hover:not(:disabled) { border-color: var(--dgo-input-border-hover); }

.dgo-input:focus-visible,
.dgo-textarea:focus-visible,
.dgo-select__field:focus-visible {
  outline: none;
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}

.dgo-input:disabled,
.dgo-textarea:disabled,
.dgo-select__field:disabled {
  background: var(--dgo-input-bg-disabled);
  color: var(--dgo-color-fg-disabled);
  cursor: not-allowed;
}

.dgo-input[aria-invalid="true"],
.dgo-textarea[aria-invalid="true"],
.dgo-select__field[aria-invalid="true"] { border-color: var(--dgo-input-border-error); }

.dgo-textarea {
  block-size: auto;
  min-block-size: calc(var(--dgo-input-h) * 2.5);
  padding-block: var(--dgo-s-2);
  resize: vertical;
  line-height: var(--dgo-lh-150);
}

/* Form field wrapper */
.dgo-field { display: flex; flex-direction: column; gap: var(--dgo-s-1_5); }
.dgo-field__label {
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
  color: var(--dgo-color-fg-default);
}
.dgo-field__label--req::after { content: " *"; color: var(--dgo-color-action-danger); }
.dgo-field__help { font-size: var(--dgo-type-caption); color: var(--dgo-color-fg-muted); }
.dgo-field__error {
  font-size: var(--dgo-type-caption);
  color: var(--dgo-color-danger-subtle-fg);
  display: flex; align-items: center; gap: var(--dgo-s-1);
}

/* Input with leading/trailing affordance */
.dgo-input-group {
  display: flex; align-items: stretch;
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  overflow: hidden;
}
.dgo-input-group:focus-within {
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}
.dgo-input-group > .dgo-input,
.dgo-input-group > .dgo-select__field {
  border: 0; border-radius: 0;
}
.dgo-input-group > .dgo-input:focus-visible { box-shadow: none; }
.dgo-input-group__addon {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  padding-inline: var(--dgo-s-3);
  color: var(--dgo-color-fg-muted);
  background: var(--dgo-color-surface-sunken);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   DGO · Kbd & Code
   ------------------------------------------------------------
   Inline keyboard chips and monospace code spans.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   25 · KBD / CODE
   ============================================================ */
.dgo-kbd {
  display: inline-flex; align-items: center;
  min-inline-size: 22px; block-size: 22px;
  padding-inline: 6px;
  font-family: var(--dgo-family-mono);
  font-size: 11px;
  font-weight: var(--dgo-wt-600);
  background: var(--dgo-kbd-bg);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-kbd-border);
  border-block-end-width: 2px;
  border-radius: var(--dgo-r-4);
}

.dgo-code-block {
  display: block;
  font-family: var(--dgo-family-mono);
  font-size: var(--dgo-type-body-sm);
  line-height: var(--dgo-lh-150);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
  padding: var(--dgo-s-4);
  border-radius: var(--dgo-radius-card);
  border: 1px solid var(--dgo-color-border-default);
  overflow-x: auto;
  white-space: pre;
}

.dgo-inline-code {
  font-family: var(--dgo-family-mono);
  font-size: 0.88em;
  padding: 2px 6px;
  border-radius: var(--dgo-r-4);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
}

/* ============================================================
   DGO · Menu & Dropdown
   ------------------------------------------------------------
   Click-anchored action lists.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   20 · MENU / DROPDOWN
   ============================================================ */
.dgo-menu {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  padding: var(--dgo-s-1);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 200px;
}
.dgo-menu__item {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-r-6);
  font-size: var(--dgo-type-body-sm);
  color: var(--dgo-color-fg-default);
  text-decoration: none;
  cursor: pointer;
}
.dgo-menu__item:hover, .dgo-menu__item:focus-visible {
  background: var(--dgo-color-surface-sunken);
  outline: none;
}
.dgo-menu__item--danger { color: var(--dgo-color-action-danger); }
.dgo-menu__item--danger:hover { background: var(--dgo-color-danger-subtle-bg); }
.dgo-menu__sep { block-size: 1px; background: var(--dgo-color-border-default); margin: var(--dgo-s-1) 0; }
.dgo-menu__label {
  font-size: var(--dgo-type-caption);
  text-transform: uppercase;
  letter-spacing: var(--dgo-tr-wide);
  color: var(--dgo-color-fg-muted);
  padding: var(--dgo-s-2) var(--dgo-s-3) var(--dgo-s-1);
}

/* ============================================================
   DGO · Metric & Stat Tile
   ------------------------------------------------------------
   Numeric KPI tiles with delta and trend.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   24 · METRIC / STAT TILE
   ============================================================ */
.dgo-metric {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  display: flex; flex-direction: column; gap: var(--dgo-s-2);
}
.dgo-metric__label {
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-color-fg-muted);
}
.dgo-metric__value {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h1);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-tightest);
  line-height: var(--dgo-lh-110);
  font-variant-numeric: tabular-nums;
  color: var(--dgo-color-fg-strong);
}
.dgo-metric__delta {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
}
.dgo-metric__delta--up { color: var(--dgo-color-success-subtle-fg); }
.dgo-metric__delta--down { color: var(--dgo-color-danger-subtle-fg); }

/* ============================================================
   DGO · Modal & Drawer
   ------------------------------------------------------------
   Overlay dialogs and edge-anchored panels.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   12 · MODAL / DRAWER
   ============================================================ */
.dgo-modal-backdrop {
  position: fixed; inset: 0;
  background: var(--dgo-color-surface-overlay);
  z-index: var(--dgo-z-modal);
  display: grid; place-items: center;
  padding: var(--dgo-s-4);
  animation: dgo-fade-in var(--dgo-motion-enter);
}
.dgo-modal {
  inline-size: 100%;
  max-inline-size: var(--dgo-modal-w);
  max-block-size: 90vh;
  display: flex; flex-direction: column;
  background: var(--dgo-color-surface-raised);
  border-radius: var(--dgo-modal-radius);
  box-shadow: var(--dgo-modal-shadow);
  overflow: clip;
  animation: dgo-modal-in var(--dgo-motion-enter);
}
.dgo-modal--lg { max-inline-size: var(--dgo-modal-w-lg); }
.dgo-modal__header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-5) var(--dgo-s-6);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-modal__title { font-size: var(--dgo-type-h3); font-weight: var(--dgo-wt-700); margin: 0; }
.dgo-modal__body { padding: var(--dgo-s-6); overflow-y: auto; }
.dgo-modal__footer {
  padding: var(--dgo-s-4) var(--dgo-s-6);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; justify-content: flex-end; gap: var(--dgo-s-2);
}
@keyframes dgo-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes dgo-modal-in { from { opacity: 0; transform: translateY(8px) scale(0.98); } to { opacity: 1; transform: none; } }

.dgo-drawer {
  position: fixed; inset-block: 0; inset-inline-end: 0;
  inline-size: var(--dgo-drawer-w); max-inline-size: 100vw;
  background: var(--dgo-color-surface-raised);
  box-shadow: var(--dgo-elevation-modal);
  display: flex; flex-direction: column;
  animation: dgo-drawer-in var(--dgo-motion-enter);
  z-index: var(--dgo-z-modal);
}
@keyframes dgo-drawer-in { from { transform: translateX(100%); } to { transform: none; } }
[dir="rtl"] .dgo-drawer { inset-inline-end: auto; inset-inline-start: 0; }

/* ============================================================
   DGO · Progress & Spinner
   ------------------------------------------------------------
   Determinate progress bar and indeterminate spinner.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   22 · PROGRESS / SPINNER
   ============================================================ */
.dgo-progress {
  inline-size: 100%;
  block-size: var(--dgo-progress-h);
  background: var(--dgo-progress-track);
  border-radius: var(--dgo-r-pill);
  overflow: hidden;
}
.dgo-progress__fill {
  block-size: 100%;
  background: var(--dgo-progress-fill);
  border-radius: inherit;
  transition: inline-size var(--dgo-motion-state);
}
.dgo-progress--accent .dgo-progress__fill { background: var(--dgo-color-action-accent); }

.dgo-progress-ring {
  inline-size: 56px; block-size: 56px;
  display: inline-grid; place-items: center;
  --_p: 0; /* @kind other */
  background:
    conic-gradient(var(--dgo-color-action-primary) calc(var(--_p) * 1%), var(--dgo-progress-track) 0);
  border-radius: 50%;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-700);
  color: var(--dgo-color-fg-default);
  position: relative;
}
.dgo-progress-ring::before {
  content: ""; position: absolute; inset: 5px;
  background: var(--dgo-color-surface-page);
  border-radius: 50%;
}
.dgo-progress-ring > span { position: relative; }

.dgo-spinner {
  inline-size: 24px; block-size: 24px;
  border: 2.5px solid var(--dgo-color-surface-sunken);
  border-block-start-color: var(--dgo-color-action-primary);
  border-radius: 50%;
  animation: dgo-spin 0.8s linear infinite;
}

/* ============================================================
   DGO · Search
   ------------------------------------------------------------
   Compound input combining icon, field, and optional clear control.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   6 · SEARCH
   ============================================================ */
.dgo-search {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-s-3);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  color: var(--dgo-color-fg-muted);
  transition: border-color var(--dgo-motion-state);
}
.dgo-search:focus-within { border-color: var(--dgo-color-action-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent); }
.dgo-search input {
  flex: 1; border: 0; background: transparent;
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  outline: none;
}

/* ============================================================
   DGO · Select
   ------------------------------------------------------------
   Styled native <select>.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   3 · SELECT (native styled)
   ============================================================ */
.dgo-select { position: relative; display: block; }
.dgo-select__field {
  appearance: none;
  -webkit-appearance: none;
  padding-inline-end: calc(var(--dgo-input-px) + 24px);
  cursor: pointer;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8' fill='none'><path d='M1 1.5L6 6.5L11 1.5' stroke='%235F5C5D' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right var(--dgo-s-3) center;
}
[dir="rtl"] .dgo-select__field {
  background-position: left var(--dgo-s-3) center;
}

/* ============================================================
   DGO · Sidebar
   ------------------------------------------------------------
   Primary navigation rail; expanded and collapsed states.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   13 · SIDEBAR
   ============================================================ */
.dgo-sidebar {
  display: flex; flex-direction: column; gap: var(--dgo-s-5);
  padding: var(--dgo-s-5) var(--dgo-s-3);
  background: var(--dgo-sidebar-bg);
  color: var(--dgo-sidebar-fg);
  block-size: 100vh;
  position: sticky;
  inset-block-start: 0;
}
.dgo-sidebar__brand { padding-inline: var(--dgo-s-2); padding-block-end: var(--dgo-s-4); border-block-end: 1px solid var(--dgo-color-border-on-brand); }
.dgo-sidebar__nav { display: flex; flex-direction: column; gap: 2px; flex: 1; }
.dgo-sidebar__group-label {
  font-size: 10px;
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-widest);
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
  padding-inline: var(--dgo-s-3);
  padding-block: var(--dgo-s-3) var(--dgo-s-1);
}

.dgo-sidebar__item {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-radius-control);
  color: rgba(255,255,255,0.78);
  text-decoration: none;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  transition: background var(--dgo-motion-state), color var(--dgo-motion-state);
  position: relative;
  min-block-size: 36px;
}
.dgo-sidebar__item:hover { color: #fff; background: rgba(255,255,255,0.06); }
.dgo-sidebar__item[aria-current="page"],
.dgo-sidebar__item--active {
  background: rgba(255,255,255,0.10);
  color: #fff;
}
.dgo-sidebar__item[aria-current="page"]::before,
.dgo-sidebar__item--active::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  inset-block: 8px;
  inline-size: 3px;
  background: var(--dgo-color-action-accent);
  border-radius: 2px;
}
.dgo-sidebar__count {
  margin-inline-start: auto;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: var(--dgo-r-pill);
  background: rgba(255,255,255,0.10);
}
.dgo-sidebar__footer {
  padding-block-start: var(--dgo-s-4);
  border-block-start: 1px solid var(--dgo-color-border-on-brand);
}

/* ============================================================
   DGO · Skeleton
   ------------------------------------------------------------
   Loading placeholders mirroring content shape.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   23 · SKELETON
   ============================================================ */
.dgo-skeleton {
  display: block;
  background:
    linear-gradient(90deg,
      var(--dgo-skeleton-base) 0%,
      var(--dgo-skeleton-shine) 50%,
      var(--dgo-skeleton-base) 100%);
  background-size: 200% 100%;
  border-radius: var(--dgo-r-6);
  animation: dgo-skeleton 1.4s linear infinite;
  min-block-size: 12px;
}
@keyframes dgo-skeleton {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
.dgo-skeleton--circle { border-radius: 50%; }

/* ============================================================
   DGO · Stepper & Pagination
   ------------------------------------------------------------
   Multi-step progress indicator and page-number navigation.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   17 · STEPPER / PAGINATION
   ============================================================ */
.dgo-stepper { display: flex; align-items: center; gap: var(--dgo-s-3); }
.dgo-stepper__step {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  color: var(--dgo-color-fg-muted);
  font-size: var(--dgo-type-body-sm);
}
.dgo-stepper__bullet {
  inline-size: 28px; block-size: 28px;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-muted);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  border: 1px solid var(--dgo-color-border-default);
}
.dgo-stepper__step[data-state="current"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-color: var(--dgo-color-action-primary);
}
.dgo-stepper__step[data-state="done"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
  border-color: var(--dgo-color-action-accent);
}
.dgo-stepper__step[data-state="current"], .dgo-stepper__step[data-state="done"] { color: var(--dgo-color-fg-default); }
.dgo-stepper__line { flex: 1; block-size: 2px; background: var(--dgo-color-border-default); border-radius: 2px; }
.dgo-stepper__step[data-state="done"] + .dgo-stepper__line { background: var(--dgo-color-action-accent); }

.dgo-pagination { display: inline-flex; align-items: center; gap: var(--dgo-s-1); }
.dgo-pagination__btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: var(--dgo-pagination-h); block-size: var(--dgo-pagination-h);
  padding-inline: var(--dgo-s-2);
  border-radius: var(--dgo-pagination-radius);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-default);
  background: transparent;
  border: 1px solid transparent;
}
.dgo-pagination__btn:hover { background: var(--dgo-color-surface-sunken); }
.dgo-pagination__btn[aria-current="page"] {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-pagination__btn:disabled { color: var(--dgo-color-fg-disabled); cursor: not-allowed; }

/* ============================================================
   DGO · Switch
   ------------------------------------------------------------
   Toggle control for instantly-applied settings.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   5 · SWITCH
   ============================================================ */
.dgo-switch {
  position: relative;
  display: inline-flex;
  inline-size: 38px; block-size: 22px;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-ink-200);
  cursor: pointer;
  transition: background-color var(--dgo-motion-state);
  flex-shrink: 0;
}
.dgo-switch::before {
  content: "";
  position: absolute;
  inset-inline-start: 2px;
  inset-block-start: 2px;
  inline-size: 18px; block-size: 18px;
  border-radius: 50%;
  background: var(--dgo-color-surface-page);
  box-shadow: var(--dgo-shadow-1);
  transition: transform var(--dgo-motion-state);
}
.dgo-switch input { position: absolute; opacity: 0; inset: 0; cursor: pointer; }
.dgo-switch:has(input:checked) { background: var(--dgo-color-action-primary); }
.dgo-switch:has(input:checked)::before { transform: translateX(16px); }
[dir="rtl"] .dgo-switch:has(input:checked)::before { transform: translateX(-16px); }
.dgo-switch:has(input:focus-visible) {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   DGO · Table & Data Grid
   ------------------------------------------------------------
   Tabular data; sortable headers, row hover, dense and comfortable densities.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   18 · TABLE / DATA GRID
   ============================================================ */
.dgo-table-wrap {
  border: 1px solid var(--dgo-table-border);
  border-radius: var(--dgo-radius-card);
  overflow: clip;
  background: var(--dgo-color-surface-raised);
}
.dgo-table {
  inline-size: 100%;
  border-collapse: collapse;
  font-size: var(--dgo-type-body-sm);
}
.dgo-table thead { background: var(--dgo-table-header-bg); }
.dgo-table th {
  text-align: start;
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-table-header-fg);
  border-block-end: 1px solid var(--dgo-table-border);
  white-space: nowrap;
}
.dgo-table td {
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  color: var(--dgo-color-fg-default);
  border-block-end: 1px solid var(--dgo-table-border);
  vertical-align: middle;
}
.dgo-table tbody tr:hover td { background: var(--dgo-table-row-hover); }
.dgo-table tbody tr:last-child td { border-block-end: 0; }
.dgo-table--striped tbody tr:nth-child(even) td { background: var(--dgo-color-surface-sunken); }

.dgo-table__num { text-align: end; font-variant-numeric: tabular-nums; }
.dgo-table__sort {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  color: inherit; cursor: pointer;
}

/* ============================================================
   DGO · Tabs
   ------------------------------------------------------------
   Horizontal segmented navigation with active indicator.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   15 · TABS
   ============================================================ */
.dgo-tabs { display: flex; flex-direction: column; gap: var(--dgo-s-5); }
.dgo-tabs__list {
  display: flex; gap: var(--dgo-s-1);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-tabs__tab {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  font-size: var(--dgo-type-body);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-muted);
  border: 0; background: transparent;
  border-block-end: var(--dgo-tabs-indicator-h) solid transparent;
  margin-block-end: -1px;
  cursor: pointer;
  transition: color var(--dgo-motion-state), border-color var(--dgo-motion-state);
}
.dgo-tabs__tab:hover { color: var(--dgo-color-fg-default); }
.dgo-tabs__tab[aria-selected="true"] {
  color: var(--dgo-color-action-primary);
  border-block-end-color: var(--dgo-tabs-indicator);
  font-weight: var(--dgo-wt-600);
}

/* ============================================================
   DGO · Toast & Snackbar
   ------------------------------------------------------------
   Transient, non-modal status notifications.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   11 · TOAST / SNACKBAR
   ============================================================ */
.dgo-toast-region {
  position: fixed;
  inset-block-end: var(--dgo-s-6);
  inset-inline-end: var(--dgo-s-6);
  display: flex; flex-direction: column; gap: var(--dgo-s-3);
  z-index: var(--dgo-z-toast);
  max-inline-size: 380px;
  pointer-events: none;
}
.dgo-toast {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  box-shadow: var(--dgo-elevation-overlay);
  pointer-events: auto;
  animation: dgo-toast-in var(--dgo-motion-enter);
}
@keyframes dgo-toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

/* ============================================================
   DGO · Tooltip & Popover
   ------------------------------------------------------------
   Hover/focus disclosure surfaces (tooltip) and click-triggered overlays (popover).

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   19 · TOOLTIP / POPOVER
   ============================================================ */
.dgo-tooltip {
  display: inline-block;
  padding: 6px 10px;
  background: var(--dgo-tooltip-bg);
  color: var(--dgo-tooltip-fg);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tooltip-radius);
  box-shadow: var(--dgo-shadow-3);
  max-inline-size: 280px;
}
.dgo-popover {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-popover-radius);
  padding: var(--dgo-popover-pad);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 220px;
}

/* ============================================================
   DGO · Topbar
   ------------------------------------------------------------
   Application top bar / app header chrome.

   Layer:        dgo-component
   Namespace:    .dgo-* (BEM)
   Depends on:   tokens/tokens.primitive.css
                 tokens/tokens.semantic.css
                 tokens/tokens.component.css
                 tokens/tokens.density.css
                 styles/base.css
   No hard-coded colors, sizes, or durations — every value is a var().
   ============================================================ */

/* ============================================================
   14 · TOPBAR
   ============================================================ */
.dgo-topbar {
  display: flex; align-items: center; gap: var(--dgo-s-4);
  block-size: var(--dgo-topbar-h);
  padding-inline: var(--dgo-s-5);
  background: var(--dgo-topbar-bg);
  border-block-end: 1px solid var(--dgo-topbar-border);
  position: sticky; inset-block-start: 0;
  z-index: var(--dgo-z-sticky);
}

/* DGO Design System 2.2 — complete technical enhancement layer */
@layer dgo-reset, dgo-base, dgo-component, dgo-pattern, dgo-utility, dgo-override;

@layer dgo-base {
  :where(a, button, input, select, textarea, summary, [tabindex]:not([tabindex="-1"])):focus-visible {
    outline: var(--dgo-focus-width) solid var(--dgo-focus-color);
    outline-offset: var(--dgo-focus-offset);
  }
  :where([aria-disabled="true"]) { cursor: not-allowed; }
  :where(img, svg, video, canvas) { block-size: auto; }
  :where(p, li, dd) { max-inline-size: var(--dgo-reading-measure); }
  :target { scroll-margin-block-start: calc(var(--dgo-topbar-h) + var(--dgo-s-4)); }
}

@layer dgo-component {
  /* Touch-target correction without forcing oversized visual glyphs. */
  :where(.dgo-btn,.dgo-pagination__btn,.dgo-chip__close,.dgo-menu__item,.dgo-tabs__tab,.dgo-check,.dgo-radio,.dgo-switch) {
    min-block-size: var(--dgo-control-target-min);
    min-inline-size: var(--dgo-control-target-min);
  }
  .dgo-check input,.dgo-radio input { flex: 0 0 auto; }
  .dgo-switch { inline-size: 44px; block-size: 28px; }
  .dgo-switch::before { inline-size: 24px; block-size: 24px; }
  .dgo-switch:has(input:checked)::before { transform: translateX(16px); }
  [dir="rtl"] .dgo-switch:has(input:checked)::before { transform: translateX(-16px); }

  /* Accordion/disclosure */
  .dgo-accordion { border: 1px solid var(--dgo-color-border-default); border-radius: var(--dgo-radius-card); overflow: clip; background: var(--dgo-color-surface-raised); }
  .dgo-accordion__item + .dgo-accordion__item { border-block-start: 1px solid var(--dgo-color-border-default); }
  .dgo-accordion__trigger { inline-size: 100%; min-block-size: var(--dgo-control-target-min); display:flex; align-items:center; justify-content:space-between; gap:var(--dgo-s-3); padding:var(--dgo-s-3) var(--dgo-s-4); text-align:start; font-weight:var(--dgo-wt-600); color:var(--dgo-color-fg-strong); background:var(--dgo-color-surface-raised); }
  .dgo-accordion__trigger:hover { background:var(--dgo-color-surface-muted); }
  .dgo-accordion__chevron { transition:transform var(--dgo-motion-state); }
  .dgo-accordion__trigger[aria-expanded="true"] .dgo-accordion__chevron { transform:rotate(180deg); }
  .dgo-accordion__panel { padding:0 var(--dgo-s-4) var(--dgo-s-4); }

  /* Segmented control */
  .dgo-segmented { display:inline-grid; grid-auto-flow:column; padding:var(--dgo-s-1); gap:var(--dgo-s-1); border:1px solid var(--dgo-color-border-default); border-radius:var(--dgo-radius-control); background:var(--dgo-color-surface-sunken); }
  .dgo-segmented__item { min-block-size:var(--dgo-control-target-min); padding-inline:var(--dgo-s-3); border-radius:var(--dgo-r-4); color:var(--dgo-color-fg-muted); }
  .dgo-segmented__item[aria-pressed="true"],.dgo-segmented__item[aria-checked="true"] { background:var(--dgo-color-surface-raised); color:var(--dgo-color-fg-strong); box-shadow:var(--dgo-shadow-1); }

  /* File upload */
  .dgo-file { display:grid; place-items:center; gap:var(--dgo-s-3); min-block-size:10rem; padding:var(--dgo-s-6); border:2px dashed var(--dgo-color-border-strong); border-radius:var(--dgo-radius-card); background:var(--dgo-color-surface-muted); text-align:center; transition:border-color var(--dgo-motion-state),background var(--dgo-motion-state); }
  .dgo-file[data-dragover="true"] { border-color:var(--dgo-color-action-accent); background:var(--dgo-color-action-primary-soft); }
  .dgo-file__input { position:absolute; inline-size:1px; block-size:1px; overflow:hidden; clip-path:inset(50%); }
  .dgo-file__list { display:grid; gap:var(--dgo-s-2); inline-size:100%; }
  .dgo-file__item { display:flex; align-items:center; gap:var(--dgo-s-3); padding:var(--dgo-s-3); border:1px solid var(--dgo-color-border-default); border-radius:var(--dgo-radius-control); background:var(--dgo-color-surface-raised); }

  /* Timeline and activity */
  .dgo-timeline { position:relative; display:grid; gap:var(--dgo-s-5); padding-inline-start:var(--dgo-s-7); }
  .dgo-timeline::before { content:""; position:absolute; inset-block:var(--dgo-s-2); inset-inline-start:var(--dgo-s-2); inline-size:2px; background:var(--dgo-color-border-default); }
  .dgo-timeline__item { position:relative; }
  .dgo-timeline__marker { position:absolute; inset-inline-start:calc(-1 * var(--dgo-s-7)); inset-block-start:var(--dgo-s-1); inline-size:var(--dgo-s-4); block-size:var(--dgo-s-4); border:3px solid var(--dgo-color-surface-page); border-radius:var(--dgo-radius-circle); background:var(--dgo-color-action-primary); box-shadow:0 0 0 1px var(--dgo-color-border-strong); }
  .dgo-timeline__time { color:var(--dgo-color-fg-muted); font-size:var(--dgo-type-caption); font-variant-numeric:tabular-nums; }

  /* Data visualization primitives */
  .dgo-chart { container-type:inline-size; padding:var(--dgo-s-4); border:1px solid var(--dgo-color-border-default); border-radius:var(--dgo-radius-card); background:var(--dgo-color-surface-raised); }
  .dgo-chart__header { display:flex; flex-wrap:wrap; align-items:flex-start; justify-content:space-between; gap:var(--dgo-s-3); margin-block-end:var(--dgo-s-4); }
  .dgo-chart__plot { min-block-size:16rem; overflow:auto; }
  .dgo-chart__legend { display:flex; flex-wrap:wrap; gap:var(--dgo-s-3); color:var(--dgo-chart-label); font-size:var(--dgo-type-caption); }
  .dgo-chart__key { display:inline-flex; align-items:center; gap:var(--dgo-s-1); }
  .dgo-chart__swatch { inline-size:var(--dgo-s-3); block-size:var(--dgo-s-3); border-radius:var(--dgo-r-2); background:var(--dgo-chart-highlight); }

  /* Command / action bar */
  .dgo-actionbar { position:sticky; inset-block-end:calc(var(--dgo-s-4) + var(--dgo-safe-bottom)); z-index:var(--dgo-z-sticky); display:flex; flex-wrap:wrap; align-items:center; gap:var(--dgo-s-3); padding:var(--dgo-s-3); border:1px solid var(--dgo-color-border-default); border-radius:var(--dgo-radius-card); background:color-mix(in srgb,var(--dgo-color-surface-raised) 92%,transparent); box-shadow:var(--dgo-elevation-overlay); backdrop-filter:blur(var(--dgo-backdrop-blur)); }

  /* Responsive data table preserving semantics */
  .dgo-table-wrap { overflow:auto; overscroll-behavior-inline:contain; }
  .dgo-table th[aria-sort] button { display:inline-flex; align-items:center; gap:var(--dgo-s-1); min-block-size:var(--dgo-control-target-min); color:inherit; }
  .dgo-table tbody tr:focus-within td { background:var(--dgo-table-row-hover); }
  @container (max-width: 38rem) {
    .dgo-chart__header { flex-direction:column; }
  }

  /* Direction-safe overlays. */
  @keyframes dgo-drawer-inline-end-in { from { transform:translateX(100%); } to { transform:none; } }
  @keyframes dgo-drawer-inline-start-in { from { transform:translateX(-100%); } to { transform:none; } }
  .dgo-drawer { animation-name:dgo-drawer-inline-end-in; }
  [dir="rtl"] .dgo-drawer { animation-name:dgo-drawer-inline-start-in; }

  /* Dialog quality */
  .dgo-modal-backdrop { backdrop-filter:blur(var(--dgo-backdrop-blur)); }
  .dgo-modal:focus { outline:none; }
  body[data-dgo-scroll-lock="true"] { overflow:hidden; }
}

@layer dgo-pattern {
  .dgo-dashboard { display:grid; grid-template-columns:minmax(0,1fr); gap:var(--dgo-s-5); }
  .dgo-dashboard__metrics { display:grid; grid-template-columns:repeat(auto-fit,minmax(13rem,1fr)); gap:var(--dgo-s-4); }
  .dgo-dashboard__main { display:grid; grid-template-columns:minmax(0,2fr) minmax(18rem,1fr); gap:var(--dgo-s-5); }
  .dgo-detail-layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(16rem,22rem); gap:var(--dgo-s-6); }
  .dgo-form-grid { display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); gap:var(--dgo-s-4); }
  .dgo-form-grid > * { grid-column:span 6; }
  .dgo-form-grid > [data-span="12"] { grid-column:1 / -1; }
  @media (max-width: 56rem) { .dgo-dashboard__main,.dgo-detail-layout { grid-template-columns:1fr; } }
  @media (max-width: 40rem) { .dgo-form-grid > * { grid-column:1 / -1; } }
}

@layer dgo-utility {
  .dgo-flow > * + * { margin-block-start:var(--dgo-flow-space,var(--dgo-s-4)); }
  .dgo-wrap { display:flex; flex-wrap:wrap; gap:var(--dgo-s-3); }
  .dgo-truncate { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .dgo-break-anywhere { overflow-wrap:anywhere; }
  .dgo-sticky-top { position:sticky; inset-block-start:0; z-index:var(--dgo-z-sticky); }
  .dgo-scroll-shadow { background:linear-gradient(var(--dgo-color-surface-raised) 30%,transparent),linear-gradient(transparent,var(--dgo-color-surface-raised) 70%) 0 100%,radial-gradient(farthest-side at 50% 0,rgba(0,0,0,.15),transparent),radial-gradient(farthest-side at 50% 100%,rgba(0,0,0,.15),transparent) 0 100%; background-repeat:no-repeat; background-size:100% 2rem,100% 2rem,100% .75rem,100% .75rem; background-attachment:local,local,scroll,scroll; }
}

@media (forced-colors:active) {
  .dgo-actionbar,.dgo-chart,.dgo-file,.dgo-accordion { border-color:CanvasText; box-shadow:none; }
  .dgo-timeline__marker { background:Highlight; border-color:Canvas; }
}
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after { scroll-behavior:auto !important; animation-duration:0.01ms !important; animation-iteration-count:1 !important; transition-duration:0.01ms !important; }
}
@media print {
  .dgo-actionbar,.dgo-toast-region,.dgo-cmdk-backdrop { display:none !important; }
  .dgo-card,.dgo-chart,.dgo-table-wrap { break-inside:avoid; box-shadow:none; }
}

/* ============================================================
   DGO v2.0 — Layout primitives
   stack · cluster · grid · sidebar · split
   ============================================================ */

/* Stack — vertical flow with consistent spacing */
.dgo-stack { display: flex; flex-direction: column; gap: var(--dgo-density-gap); }
.dgo-stack--1 { gap: var(--dgo-s-1); }
.dgo-stack--2 { gap: var(--dgo-s-2); }
.dgo-stack--3 { gap: var(--dgo-s-3); }
.dgo-stack--4 { gap: var(--dgo-s-4); }
.dgo-stack--5 { gap: var(--dgo-s-5); }
.dgo-stack--6 { gap: var(--dgo-s-6); }
.dgo-stack--8 { gap: var(--dgo-s-8); }
.dgo-stack--12 { gap: var(--dgo-s-12); }

/* Cluster — wrapping horizontal flow */
.dgo-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--dgo-density-gap);
}
.dgo-cluster--2 { gap: var(--dgo-s-2); }
.dgo-cluster--3 { gap: var(--dgo-s-3); }
.dgo-cluster--4 { gap: var(--dgo-s-4); }
.dgo-cluster--end { justify-content: flex-end; }
.dgo-cluster--between { justify-content: space-between; }

/* Row — horizontal flex, non-wrapping by default */
.dgo-row {
  display: flex;
  gap: var(--dgo-density-gap);
  align-items: center;
}
.dgo-row--top    { align-items: flex-start; }
.dgo-row--bottom { align-items: flex-end; }
.dgo-row--baseline { align-items: baseline; }
.dgo-row--stretch { align-items: stretch; }
.dgo-row--between { justify-content: space-between; }
.dgo-row--end     { justify-content: flex-end; }
.dgo-row--center  { justify-content: center; }

.dgo-spacer { flex: 1 1 auto; }

/* Grid */
.dgo-grid {
  display: grid;
  gap: var(--dgo-density-gap);
}
.dgo-grid--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.dgo-grid--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.dgo-grid--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.dgo-grid--6 { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.dgo-grid--12 { grid-template-columns: repeat(12, minmax(0, 1fr)); }
.dgo-grid--auto { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }

@media (max-width: 900px) {
  .dgo-grid--3, .dgo-grid--4, .dgo-grid--6 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dgo-grid--12 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 600px) {
  .dgo-grid--2, .dgo-grid--3, .dgo-grid--4, .dgo-grid--6 { grid-template-columns: 1fr; }
  .dgo-grid--12 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Sidebar layout — fixed-width sidebar + fluid content */
.dgo-sidebar-layout {
  display: grid;
  grid-template-columns: var(--dgo-sidebar-w) minmax(0, 1fr);
  min-height: 100vh;
}
.dgo-sidebar-layout--collapsed {
  grid-template-columns: var(--dgo-sidebar-w-collapsed) minmax(0, 1fr);
}

@media (max-width: 900px) {
  .dgo-sidebar-layout { grid-template-columns: 1fr; }
}

/* Split — two columns, prefer space-between */
.dgo-split {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--dgo-s-4);
}

/* App shell scaffold */
.dgo-app {
  display: grid;
  grid-template-rows: auto 1fr;
  min-height: 100vh;
}
.dgo-app__topbar { grid-row: 1; }
.dgo-app__body   { grid-row: 2; min-height: 0; }

/* Container queries (component-level reflow) */
.dgo-cq { container-type: inline-size; }

/* ============================================================
   DGO v2.0 — Modern Reset
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  -moz-text-size-adjust: 100%;
  text-size-adjust: 100%;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd { margin: 0; }
ul[role="list"], ol[role="list"] { list-style: none; padding: 0; margin: 0; }

a { color: inherit; }
img, picture, video, canvas, svg { display: block; max-width: 100%; }
input, button, textarea, select { font: inherit; color: inherit; }

button {
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

table { border-collapse: collapse; }
[hidden] { display: none !important; }

/* Focus outline replaced everywhere with semantic focus ring */
:focus { outline: none; }
:focus-visible { outline: none; }

/* Logical-only margin reset for RTL safety */
ul, ol {
  padding-inline-start: 1.5rem;
}

/* ============================================================
   DGO Design System v2.0 — Component Tokens
   Per-component bindings. Themes/density override here.
   ============================================================ */

:root {
  /* ---------- Button ---------- */
  --dgo-btn-radius:           var(--dgo-radius-control);
  --dgo-btn-fw:               var(--dgo-wt-600);
  --dgo-btn-tracking:         var(--dgo-tr-normal);
  --dgo-btn-h-sm:             32px;
  --dgo-btn-h-md:             40px;
  --dgo-btn-h-lg:             48px;
  --dgo-btn-px-sm:            var(--dgo-s-3);
  --dgo-btn-px-md:            var(--dgo-s-4);
  --dgo-btn-px-lg:            var(--dgo-s-5);

  /* ---------- Input ---------- */
  --dgo-input-radius:         var(--dgo-radius-control);
  --dgo-input-h:              40px;
  --dgo-input-px:             var(--dgo-s-3);
  --dgo-input-bg:             var(--dgo-color-surface-page);
  --dgo-input-bg-disabled:    var(--dgo-color-surface-muted);
  --dgo-input-border:         var(--dgo-color-border-strong);
  --dgo-input-border-hover:   var(--dgo-color-border-stronger);
  --dgo-input-border-focus:   var(--dgo-color-action-primary);
  --dgo-input-border-error:   var(--dgo-color-danger-strong-bg);
  --dgo-input-placeholder:    var(--dgo-color-fg-subtle);

  /* ---------- Card ---------- */
  --dgo-card-bg:              var(--dgo-color-surface-raised);
  --dgo-card-border:          var(--dgo-color-border-default);
  --dgo-card-radius:          var(--dgo-radius-card);
  --dgo-card-pad:             var(--dgo-s-5);
  --dgo-card-shadow:          var(--dgo-elevation-card);
  --dgo-card-shadow-hover:    var(--dgo-elevation-raised);

  /* ---------- Badge / pill ---------- */
  --dgo-badge-radius:         var(--dgo-r-pill);
  --dgo-badge-h:              22px;
  --dgo-badge-px:             var(--dgo-s-2);
  --dgo-badge-fs:             var(--dgo-size-12);
  --dgo-badge-fw:             var(--dgo-wt-600);
  --dgo-badge-tracking:       var(--dgo-tr-normal);

  /* ---------- Tag (square) ---------- */
  --dgo-tag-radius:           var(--dgo-r-4);
  --dgo-tag-h:                24px;

  /* ---------- Alert / Banner ---------- */
  --dgo-alert-radius:         var(--dgo-radius-control);
  --dgo-alert-pad:            var(--dgo-s-4);
  --dgo-alert-border-w:       1px;

  /* ---------- Modal / Drawer ---------- */
  --dgo-modal-radius:         var(--dgo-radius-frame);
  --dgo-modal-pad:            var(--dgo-s-6);
  --dgo-modal-w:              560px;
  --dgo-modal-w-lg:           800px;
  --dgo-modal-shadow:         var(--dgo-elevation-modal);
  --dgo-drawer-w:             400px;

  /* ---------- Popover / Tooltip ---------- */
  --dgo-popover-radius:       var(--dgo-radius-card);
  --dgo-popover-pad:          var(--dgo-s-3);
  --dgo-popover-shadow:       var(--dgo-elevation-popover);
  --dgo-tooltip-bg:           var(--dgo-ink-900);
  --dgo-tooltip-fg:           var(--dgo-ink-0);
  --dgo-tooltip-radius:       var(--dgo-r-6);

  /* ---------- Table ---------- */
  --dgo-table-row-h:          44px;
  --dgo-table-cell-px:        var(--dgo-s-3);
  --dgo-table-header-bg:      var(--dgo-color-surface-sunken);
  --dgo-table-header-fg:      var(--dgo-color-fg-muted);
  --dgo-table-row-hover:      var(--dgo-green-50);
  --dgo-table-border:         var(--dgo-color-border-default);

  /* ---------- Sidebar / Topbar ---------- */
  --dgo-sidebar-w:            260px;
  --dgo-sidebar-w-collapsed:  68px;
  --dgo-sidebar-bg:           var(--dgo-color-surface-inverse);
  --dgo-sidebar-fg:           rgba(255,255,255,0.82);
  --dgo-topbar-h:             64px;
  --dgo-topbar-bg:            var(--dgo-color-surface-page);
  --dgo-topbar-border:        var(--dgo-color-border-default);

  /* ---------- Tabs ---------- */
  --dgo-tabs-indicator-h:     2px;
  --dgo-tabs-indicator:       var(--dgo-color-action-accent);

  /* ---------- Pagination ---------- */
  --dgo-pagination-h:         36px;
  --dgo-pagination-radius:    var(--dgo-radius-control);

  /* ---------- Progress ---------- */
  --dgo-progress-h:           6px;
  --dgo-progress-track:       var(--dgo-color-surface-sunken);
  --dgo-progress-fill:        var(--dgo-color-action-primary);

  /* ---------- Skeleton ---------- */
  --dgo-skeleton-base:        var(--dgo-ink-50);
  --dgo-skeleton-shine:       var(--dgo-ink-100);

  /* ---------- Code ---------- */
  --dgo-code-bg:              var(--dgo-color-surface-sunken);
  --dgo-code-fg:              var(--dgo-green-900);
  --dgo-kbd-bg:               var(--dgo-color-surface-page);
  --dgo-kbd-border:           var(--dgo-color-border-strong);

  /* ---------- Command Palette (v2.1) ---------- */
  --dgo-cmdk-w:               clamp(320px, 90vw, 640px); /* @kind spacing */
  --dgo-cmdk-bg:              var(--dgo-color-surface-raised);
  --dgo-cmdk-border:          var(--dgo-color-border-default);
  --dgo-cmdk-radius:          var(--dgo-radius-frame);
  --dgo-cmdk-shadow:          var(--dgo-elevation-modal);
  --dgo-cmdk-pad:             var(--dgo-s-2);
  --dgo-cmdk-input-h:         48px;
  --dgo-cmdk-input-fs:        var(--dgo-type-body-lg);
  --dgo-cmdk-input-bg:        transparent;
  --dgo-cmdk-item-h:          44px;
  --dgo-cmdk-item-pad:        var(--dgo-s-3);
  --dgo-cmdk-item-radius:     var(--dgo-radius-control);
  --dgo-cmdk-item-fs:         var(--dgo-type-body);
  --dgo-cmdk-item-bg:         transparent;
  --dgo-cmdk-item-bg-active:  var(--dgo-green-50);
  --dgo-cmdk-item-fg-active:  var(--dgo-color-fg-strong);
  --dgo-cmdk-meta-fg:         var(--dgo-color-fg-muted);
  --dgo-cmdk-group-label-fs:  var(--dgo-size-12);
  --dgo-cmdk-group-label-fg:  var(--dgo-color-fg-muted);
  --dgo-cmdk-backdrop-bg:     var(--dgo-color-surface-overlay);
  --dgo-cmdk-z:               var(--dgo-z-modal);
}

/* ============================================================
   DGO v2.0 — Density modes
   [data-density="comfortable"] (default) | [data-density="compact"]
   ============================================================ */

:root,
[data-density="comfortable"] {
  --dgo-density-pad:          var(--dgo-s-4);
  --dgo-density-pad-y:        var(--dgo-s-3);
  --dgo-density-gap:          var(--dgo-s-3);
  --dgo-density-row:          48px;

  --dgo-btn-h-sm:             32px;
  --dgo-btn-h-md:             40px;
  --dgo-btn-h-lg:             48px;
  --dgo-input-h:              40px;
  --dgo-table-row-h:          48px;
  --dgo-card-pad:             var(--dgo-s-5);
}

[data-density="compact"] {
  --dgo-density-pad:          var(--dgo-s-2);
  --dgo-density-pad-y:        var(--dgo-s-1_5);
  --dgo-density-gap:          var(--dgo-s-2);
  --dgo-density-row:          36px;

  --dgo-btn-h-sm:             28px;
  --dgo-btn-h-md:             32px;
  --dgo-btn-h-lg:             40px;
  --dgo-input-h:              32px;
  --dgo-table-row-h:          36px;
  --dgo-card-pad:             var(--dgo-s-4);

  /* Command palette compacts with the rest of the system */
  --dgo-cmdk-input-h:         40px;
  --dgo-cmdk-item-h:          36px;
  --dgo-cmdk-item-pad:        var(--dgo-s-2);
}

/* DGO Design System 2.2 — technical expansion tokens */
:root {
  --dgo-control-target-min: 44px;
  --dgo-control-target-compact: 36px;
  --dgo-focus-width: 3px;
  --dgo-focus-offset: 3px;
  --dgo-focus-color: var(--dgo-color-border-focus);
  --dgo-duration-progress: 800ms;
  --dgo-duration-skeleton: 1400ms;
  --dgo-duration-spin: 800ms;
  --dgo-ease-spring: cubic-bezier(.2,.8,.2,1);
  --dgo-content-xs: 20rem;
  --dgo-content-sm: 30rem;
  --dgo-content-md: 48rem;
  --dgo-content-lg: 64rem;
  --dgo-content-xl: 80rem;
  --dgo-chart-grid: var(--dgo-color-border-default);
  --dgo-chart-label: var(--dgo-color-fg-muted);
  --dgo-chart-highlight: var(--dgo-color-action-accent);
  --dgo-backdrop-blur: var(--dgo-blur-4);
  --dgo-safe-bottom: env(safe-area-inset-bottom, 0px);
  --dgo-safe-top: env(safe-area-inset-top, 0px);
  --dgo-reading-measure: 70ch;
}
[data-density="compact"] { --dgo-control-target-min: var(--dgo-control-target-compact); }
@media (prefers-reduced-motion: reduce) {
  :root { --dgo-duration-progress: 0ms; --dgo-duration-skeleton: 0ms; --dgo-duration-spin: 0ms; }
}

/* ============================================================
   DGO Design System v2.0 — Primitive Tokens
   Raw values. Never reference these directly from components.
   ============================================================ */

:root {
  /* ---------- Color: Primary Green (NITDA-sibling) ---------- */
  --dgo-green-50:   #EAF3EF;
  --dgo-green-100:  #CFE3D8;
  --dgo-green-200:  #A4CCB7;
  --dgo-green-300:  #6FAE8E;
  --dgo-green-400:  #3D8E69;
  --dgo-green-500:  #1A7250;
  --dgo-green-600:  #0C603F;
  --dgo-green-700:  #05583B;   /* Brand Deep Green (PANTONE 7484C sibling) */
  --dgo-green-800:  #033F2A;
  --dgo-green-900:  #022819;
  --dgo-green-950:  #011610;

  /* ---------- Color: Accent / Smart Green (operational/active) ---------- */
  --dgo-smart-50:   #E6F7ED;
  --dgo-smart-100:  #C2EED2;
  --dgo-smart-200:  #8BD9A9;
  --dgo-smart-300:  #45C578;
