  --dgo-smart-600:  #0D7234;
  --dgo-smart-700:  #0A5828;
  --dgo-smart-800:  #07401D;

  /* ---------- Color: Ink (warm-cool neutral) ---------- */
  --dgo-ink-0:      #FFFFFF;
  --dgo-ink-25:     #FAFAF9;
  --dgo-ink-50:     #F5F4F4;
  --dgo-ink-100:    #E8E6E7;
  --dgo-ink-200:    #C4C3C3;
  --dgo-ink-300:    #A09E9F;
  --dgo-ink-400:    #807D7E;
  --dgo-ink-500:    #5F5C5D;
  --dgo-ink-600:    #4A4849;
