  --dgo-tr-wide:     0.06em; /* @kind font */
  --dgo-tr-wider:    0.12em; /* @kind font */
  --dgo-tr-widest:   0.18em; /* @kind font */

  /* ---------- Spacing: 4pt grid, 0–24 ---------- */
  --dgo-s-0:    0; /* @kind spacing */
  --dgo-s-px:   1px;
  --dgo-s-0_5:  2px;
  --dgo-s-1:    4px;
  --dgo-s-1_5:  6px;
  --dgo-s-2:    8px;
  --dgo-s-3:    12px;
  --dgo-s-4:    16px;
  --dgo-s-5:    20px;
  --dgo-s-6:    24px;
  --dgo-s-7:    28px;
  --dgo-s-8:    32px;
  --dgo-s-9:    36px;
  --dgo-s-10:   40px;
  --dgo-s-11:   44px;
  --dgo-s-12:   48px;
  --dgo-s-14:   56px;
  --dgo-s-16:   64px;
  --dgo-s-20:   80px;
  --dgo-s-24:   96px;

  /* ---------- Radius ---------- */
  --dgo-r-0:    0; /* @kind radius */
  --dgo-r-2:    2px;
  --dgo-r-4:    4px;
  --dgo-r-6:    6px;
  --dgo-r-8:    8px;
  --dgo-r-10:   10px;
  --dgo-r-12:   12px;
  --dgo-r-16:   16px;
  --dgo-r-18:   18px;
  --dgo-r-24:   24px;
