}

function previewPanel(preview){
  if(!preview) return '';
  const body=preview.previewable
    ?`<div class="email-frame"><iframe title="Attachment preview: ${esc(preview.name)}" src="${esc(preview.url)}" sandbox referrerpolicy="no-referrer"></iframe></div>`
