let messages = [], sending = false;
export async function mount(el){hydrateGovernance();render(el); }
function supportPanel(){ const ctx=SupportService.buildContext(); return `<section class="panel"><h2>Contextual Support</h2><p class="meta">Captures current route, selected reference, last error, pending writes and recent receipts for support triage.</p><div class="form-row"><select id="support-category">${SupportRoutingConfig.categories.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}</select><input id="support-ref" placeholder="Reference / Task ID" value="${esc(ctx.selectedId||'')}"></div><textarea id="support-message" rows="3" placeholder="Describe the issue, required reassignment, timeline concern, or clarification…"></textarea><div class="toolbar"><button class="btn" id="support-submit">Submit Support Request</button></div><details><summary>Support context preview</summary><pre class="pre">${esc(JSON.stringify(ctx,null,2))}</pre></details></section>`; }
