export async function mount(el){hydrateGovernance();render(el); }
function badgeTone(ds) { return ds === 'dispatched' ? 'ok' : ds === 'closed' ? 'info' : ds === 'no-dispatch' ? 'warn' : ''; }
const CHANNELS = ['Internal Memo', 'Email', 'Courier', 'Portal Upload'];
function queue(s) {
