    if (!await confirmAction({ title: 'Confirm dispatch', body: `<p><b>${esc(sel.title)}</b></p><p>Channel: ${esc(channel)} · Recipient: ${esc(recipient)}</p>` })) return;
    const at = new Date().toISOString();
