      State.patch({
        tracking: s.tracking.map(x => x.id === sel.id ? { ...x, dispatchStatus: 'dispatched', dispatchedAt: at, dispatchChannel: channel, dispatchRecipient: recipient } : x),
        dispatches: [record, ...s.dispatches]
