    if (!reason) return toast('A reason is required to mark no-dispatch', 'error');
    if (!await confirmAction({ title: 'Mark as no dispatch required', body: `<p><b>${esc(sel.title)}</b></p><p>Reason: ${esc(reason)}</p>` })) return;
