function wire(el,item,s,r){el.querySelectorAll('[data-exec-select]').forEach(b=>b.onclick=()=>{UIState.set('executive',{selected:b.dataset.execSelect,md:'detail'});render(el);resetDetailScroll(el)});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('executive',{md:'list'});render(el)});el.querySelector('[data-sync-live]')?.addEventListener('click',syncLive);el.querySelector('[data-switch-role]')?.addEventListener('click',()=>{location.hash='#/settings';});if(!item)return;const ref=item.referenceId||item.id||'';const update=async(action,label,patch)=>{if(!await confirmAction({title:label,body:`<p>${esc(item.subject||item.title||item.id)}</p>${actionPreview({reference:ref,action,label})}`}))return;await executeOwnedAction('executive',action,()=>{patch();State.patch({correspondence:s.correspondence,tracking:s.tracking,approvals:s.approvals,comments:s.comments,audit:s.audit},{module:'executive',action,ref});toast(label,'success');render(el);},{ref});};const decide=(action,label,status)=>update(action,label,()=>{const res=setCorrespondenceStatus(s,item.id,status,s.profile.email,{surface:'executive'});if(res){s.correspondence=res.patch.correspondence;s.audit=res.patch.audit;}});el.querySelector('[data-exec-approve]')?.addEventListener('click',()=>decide('executive-approve','Executive approval recorded','Accepted'));el.querySelector('[data-exec-return]')?.addEventListener('click',()=>decide('executive-return','Declined / rejected by DGCEO','Declined'));el.querySelector('[data-exec-escalate]')?.addEventListener('click',()=>decide('executive-escalate','Delegated via EA','Delegated'));el.querySelector('[data-append-minute]')?.addEventListener('click',()=>appendMinute(el,item,s));el.querySelector('[data-route-task]')?.addEventListener('click',()=>routeTask(el,item,s));el.querySelector('[data-apply-ai]')?.addEventListener('click',()=>{if(!item){toast('Select a correspondence item first','info');return;}requestSync({source:'executive',mode:'endpoint',endpoint:'AI_DOC_ANALYSIS',payload:{operation:'classify',referenceId:item.referenceId||item.id,subject:item.subject,category:item.category,priority:item.priority}}).then(()=>toast('AI classification requested from governed endpoint','success')).catch(()=>toast('AI classification endpoint unavailable; existing metadata retained','error'));});el.querySelector('[data-export-decision]')?.addEventListener('click',()=>exportJson('executive-decision.json',{at:new Date().toISOString(),item,actor:s.profile}));}
async function appendMinute(el,item,s){const note=el.querySelector('[data-minute]')?.value||'';if(!note.trim())return toast('Enter a quick minute first','error');if(!await confirmAction({title:'Append quick minute',body:`<p>${esc(item.subject)}</p><pre class="preview-box">${esc(note)}</pre>`}))return;await executeOwnedAction('executive','append-minute',()=>{State.patch({comments:[{id:crypto.randomUUID(),referenceId:item.referenceId||item.id,body:note,author:s.profile.email,ts:new Date().toISOString(),type:'executive-minute'},...s.comments]},{module:'executive',action:'append-minute',ref:item.referenceId||item.id});},{ref:item.referenceId||item.id});invoke('DYNAMIC_ACTIONS',{action:'appendMinute',ref:item.referenceId||item.id,note}).catch(()=>toast('Minute saved locally; sync queued','error'));toast('Minute appended','success');render(el);}
async function routeTask(el,item,s){const assignee=el.querySelector('[data-route-assignee]')?.value,dept=el.querySelector('[data-route-dept]')?.value,priority=el.querySelector('[data-route-priority]')?.value,notes=el.querySelector('[data-route-notes]')?.value;if(!assignee)return toast('Select an assignee','error');const draft=createTask(s,{title:item.subject,referenceId:item.referenceId||item.id,assignedTo:assignee,assignedToDsu:dept,priority,description:notes},s.profile.email,{surface:'executive'}).task;if(!await confirmAction({title:'Route to Assignment',body:`<p>${esc(item.subject)}</p>${actionPreview(draft)}`,confirmText:'Open Assignment',cancelText:'Cancel'}))return;await executeOwnedAction('executive','route-task',()=>{State.patch({selectedId:item.referenceId||item.id},{module:'executive',action:'route-task',ref:item.referenceId||item.id});},{ref:item.referenceId||item.id});location.hash='#/single-assignment';toast('Opened Assignment workflow','success');}
