function matrixRows(s){return s.tracking.map(t=>{const ref=String(t.referenceId||t.RefIDD||t.Reference_ID||'');const doc=s.activities.find(a=>String(a.id)===ref||String(a.referenceId)===ref);const relEmails=relatedEmailsFor({referenceId:ref,title:t.title},s);const start=t.start||t.created||t.Created||new Date().toISOString();const due=t.due||t.DueDate||'';let derived=t.status||t.Progress||'Pending';let slaPercent=0;if(due){const total=new Date(due)-new Date(start);const elapsed=Date.now()-new Date(start);slaPercent=Math.max(0,Math.min(100,(elapsed/(total||1))*100));if(!isComplete(derived)&&new Date(due)<new Date())derived='Overdue';}return{...t,sourceId:inferSourceId({...t,parentDoc:doc,relatedEmails:relEmails}),__id:String(t.id),referenceId:ref||'—',title:t.title||t.Title||'Untitled task',assignedTo:t.assignedTo||t.AssignedTo||'N/A',category:t.category||t.Classification||doc?.category||'Standard',derivedStatus:derived,slaPercent,parentDoc:doc,relatedEmails:relEmails};});}
function rowsFor(s){if(tab==='matrix')return matrixRows(s);if(tab==='all')return s.activities.map(a=>({referenceId:a.referenceId||'—',title:a.title,status:status(a),category:a.category||'—',created:fmtDate(a.created),__id:a.id,__route:'activities'}));if(tab==='tasks')return s.tracking.map(t=>({referenceId:t.referenceId||'—',title:t.title,assignedTo:t.assignedTo||'—',priority:t.priority||'normal',status:t.status,__id:t.id,__route:'orchestrator'}));if(tab==='comments')return s.comments.map(c=>({referenceId:c.referenceId||'—',author:c.author||'—',body:(c.body||'').slice(0,60),ts:fmtDate(c.ts||''),__id:c.id,__route:'comments'}));return s.activities.filter(a=>s.tracking.some(t=>t.referenceId===a.referenceId)).map(a=>{const t=s.tracking.find(t=>t.referenceId===a.referenceId);return{referenceId:a.referenceId,doc:a.title,task:t.title,status:t.status,__id:a.id,__route:'activities'}});}
function colsFor(){if(tab==='matrix')return[{key:'referenceId',label:'Trace ID'},{key:'title',label:'Execution Node'},{key:'assignedTo',label:'Executor'},{key:'category',label:'Classification'},{key:'derivedStatus',label:'Governance'}];if(tab==='all')return[{key:'referenceId',label:'Reference'},{key:'title',label:'Title'},{key:'status',label:'Status'},{key:'category',label:'Category'},{key:'created',label:'Date'}];if(tab==='tasks')return[{key:'referenceId',label:'Reference'},{key:'title',label:'Title'},{key:'assignedTo',label:'Assigned To'},{key:'priority',label:'Priority'},{key:'status',label:'Status'}];if(tab==='comments')return[{key:'referenceId',label:'Reference'},{key:'author',label:'Author'},{key:'body',label:'Comment'},{key:'ts',label:'Date'}];return[{key:'referenceId',label:'Reference'},{key:'doc',label:'Document'},{key:'task',label:'Task'},{key:'status',label:'Status'}];}
