}
@media(min-width:1001px){
  .dg-layout>*{min-height:0;overflow:visible}
}
@media(max-width:900px){
  .md-back{display:inline-flex;margin-bottom:8px}
  .split[data-md="detail"]>*:first-child{display:none}
  .split[data-md="list"]>*:last-child{display:none}
}
@media(max-width:1000px){
  .dg-layout .md-back{display:inline-flex;margin-bottom:8px}
  .dg-layout[data-md="detail"]>.panel-inbox{display:none}
  .dg-layout[data-md="list"]>#panel-details{display:none}
  .dg-layout[data-md="list"]>.panel-actions{display:none}
}

