.dgo-sidebar__identity{padding:14px 16px;border-top:1px solid rgba(255,255,255,.11)}.dgo-sidebar__identity b{display:block;font-size:13px}.dgo-sidebar__identity small{display:block;color:rgba(255,255,255,.62);font-size:11px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dgo-workarea{flex-direction:column;min-width:0;min-height:0}.dgo-topbar{height:var(--dgo-shell-topbar-h);display:flex;align-items:center;gap:12px;padding:0 20px;background:var(--dgo-color-surface-page,#fff);border-bottom:1px solid var(--dgo-color-border-default,#dfe7e2);position:relative;z-index:var(--dgo-z-sticky,100)}.dgo-route-title{display:flex;flex-direction:column}.dgo-route-title small{font-weight:800;text-transform:uppercase;color:var(--dgo-color-fg-brand)}.dgo-route-title b{font-family:var(--dgo-family-display,Outfit,system-ui);font-size:17px;color:var(--dgo-color-fg-strong,#111)}.dgo-search-trigger{display:flex;align-items:center;gap:9px;width:330px;max-width:36vw;border-radius:10px;border:1px solid transparent;background:var(--dgo-color-surface-sunken,#f4f7f4);color:var(--dgo-color-fg-muted,#626a64);padding:0 12px;cursor:pointer}.dgo-search-trigger:hover{border-color:var(--dgo-color-border-default,#dfe7e2)}.dgo-search-trigger span:nth-child(2){flex:1;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dgo-search-trigger kbd{font-size:11px;border:1px solid var(--dgo-color-border-default,#dfe7e2);background:var(--dgo-color-surface-page,#fff);border-radius:5px;padding:1px 5px}
