/* ============================================================
   R11.6 CONSOLIDATION — data-independent layout corrections
   (verified via headless render; no !important, single-owner)
   ============================================================ */
/* Kill the collapsed-panel stretch void: a collapsed <details> must not
   inflate to its open sibling's height. */
.cc-support-panels{align-items:start}
.cc-progressive:not([open]){min-height:0}
/* Fluid action grid: however many cards are visible (RBAC may hide some),
   they fill the row instead of leaving a large empty panel. */
.cc-action-grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr))}
/* KPI / metric labels must break only at spaces, never mid-word
   (fixes "REFER ENCES" / "DISPAT CHED" on narrow cards). */
.kpi small,.cc-kpi-band .kpi small,.dgo-kpi-card__top>span:first-child,.dgo-stat__label{overflow-wrap:normal;word-break:keep-all;hyphens:none}
/* Mobile KPI band: two equal columns that fill the row so uppercase
   labels have room and never clip. */
@media(max-width:560px){
  .cc-kpi-band .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .cc-kpi-band .kpi{min-width:0}
}
/* .cc-kpi-band is a wrapper, not a metrics grid. A grouped rule
   (.kpis,.stat-row,.cc-kpi-band{display:grid;...}) wrongly made it a
   multi-column grid, so on narrow widths .kpis was trapped in the first
   track and the band's right half went empty. The band is block; only its
   inner .kpis is the grid. */
.cc-kpi-band{display:block}
/* R11.6 P0-3 — single canonical KPI grid (deterministic, width-following).
   One auto-fit rule for every .kpis (incl. .cc-kpi-band); overrides the prior
   non-monotonic fixed-column @media/@container rules by specificity + order,
   so column count follows available width consistently across all routes. */
.kpis,.cc-kpi-band .kpis{grid-template-columns:repeat(auto-fit,minmax(min(100%,150px),1fr))}
/* R11.6 §E — KPI metric cards: 3px smart-green left accent (flat brand). */
.kpi,.dgo-metric{border-left:3px solid var(--dgo-color-action-accent,#17B255)}
/* R11.6 fix (data-surfaced) — the workspace is a fixed-height flex column; sticky toolbars/
   filter bars must NOT shrink or clip when the record list is tall, otherwise their controls
   (search, filters, action buttons) get compressed and hidden. Keep natural height; the list
   pane owns the scroll. */
.toolbar,.dgo-toolbar,.dgo-filterbar,.filterbar{flex:0 0 auto;min-block-size:max-content;overflow:visible}
/* R11.6 §C — focus-visible parity: every clickable surface with a hover-only affordance
   must present the same state to keyboard users, plus the canonical focus ring. */
.action-card:focus-visible{transform:translateY(-1px);box-shadow:var(--dgo-shadow-3,0 8px 22px rgba(5,88,59,.12)),var(--focus)}
.list-item:focus-visible{border-color:var(--a);box-shadow:var(--focus)}
.command-item:focus-visible{background:var(--sunken);box-shadow:var(--focus)}
.navlink:focus-visible{background:#A2E0BB20;color:#fff;box-shadow:var(--focus)}
.dgo-sidebar__item:focus-visible{background:rgba(255,255,255,.07);box-shadow:var(--focus)}
.dgo-iconbtn:focus-visible{background:var(--dgo-color-surface-sunken,#f4f7f4);box-shadow:var(--focus)}
.dgo-search-trigger:focus-visible{border-color:var(--dgo-color-border-default,#dfe7e2);box-shadow:var(--focus)}
tr.row-link:focus-visible>td{background:var(--sunken)}

/* ============================================================
   R11.6 Phase-2 — layout / responsiveness / a11y fixes
   ============================================================ */

/* 2.1 — Reference-ID overflow-wrap: long IDs (e.g. "DGO-2024-R11-123456") must
   wrap rather than force horizontal page scroll on narrow viewports. */
.dgo-record-row__ref{
  min-inline-size:0;
  overflow-wrap:anywhere;
  word-break:break-word;
  max-inline-size:min(100%,22ch);
}

/* 2.2 — 320 px topbar containment.
   At 480 px and below the topbar width (320 px device = 300 px content after
   padding) cannot fit 7 icon-sized flex items simultaneously. Hide the secondary
   utility buttons (workspace guide, data-sync) so the hamburger, search, theme,
   density and persona remain reachable. Theme and density are intentionally kept
   because they affect contrast and layout density, which are accessibility concerns. */
@media (max-width:480px){
  [data-guide],[data-sync]{display:none !important;}
}

/* 2.3 — Mobile touch-target floor (WCAG 2.2 SC 2.5.8).
   Icon buttons render at 38 × 38 px by design on desktop. On touch viewports
   (≤ 900 px) the tap target must be at least 44 × 44 px via padding rather than
   by growing the visible icon, so the visual design is preserved. */
@media (max-width:900px){
  .dgo-iconbtn{
    min-inline-size:44px;
    min-block-size:44px;
  }
}

/* 2.4 — dvh: the max-height:640px fallback block (line ~195) overrides the
   authoritative dvh block (lines ~399-403). Re-assert dvh here so the
   non-dvh rule cannot leak through if the cascade order is ever reorganised. */
@media (max-height:640px){
